    gkyl_dg_div_op_range(
      sm->mem_geo, &app->basis, k, mom_out, k, Jmom_in, 0, app->gk_geom->geo_int.jacobgeo,
      &app->local
    );
  }
}

static void
gk_neut_species_kinetic_moment_calc(
  const struct gk_species_moment *sm, const struct gkyl_range phase_rng,
  const struct gkyl_range conf_rng, const struct gkyl_array *fin
)
{
  if (sm->is_maxwellian_moms) {
    gkyl_vlasov_lte_moments_advance(sm->vlasov_lte_moms, &phase_rng, &conf_rng, fin, sm->marr);
  } else {
    gkyl_dg_updater_moment_advance(sm->mcalc, &phase_rng, &conf_rng, fin, sm->marr);
  }
}

static void
gk_neut_species_kinetic_moment_release(
  const struct gkyl_gyrokinetic_app *app, const struct gk_species_moment *sm
)
{
  gkyl_array_release(sm->marr);
  if (app->use_gpu) {
    gkyl_array_release(sm->marr_host);
  }

  if (sm->is_integrated) {
    gkyl_dg_updater_moment_release(sm->mcalc);
  } else {
    if (sm->is_maxwellian_moms) {
      gkyl_vlasov_lte_moments_release(sm->vlasov_lte_moms);
    } else {
      gkyl_dg_updater_moment_release(sm->mcalc);
    }

    // Free the weak division memory.
    gkyl_dg_bin_op_mem_release(sm->mem_geo);
  }
}

static void
gk_neut_species_kinetic_moment_init(
  struct gkyl_gyrokinetic_app *app, struct gk_neut_species *gkns, struct gk_species_moment *sm,
  enum gkyl_distribution_moments mom_type, bool is_integrated
)
{
  sm->diag_jacobgeo_div_func = gk_neut_species_moment_diag_jacobgeo_div_disabled;

  // Initialize kinetic neutral species moment object.
  if (sm->is_integrated) {
    // Create moment operator.
    struct gkyl_mom_canonical_pb_auxfields can_pb_inp = {.hamil = gkns->hamil};
    sm->mcalc = gkyl_dg_updater_moment_new(
      &gkns->grid, &app->basis, &gkns->basis, &app->local, &gkns->local_vel, &gkns->local,
      gkns->model_id, &can_pb_inp, mom_type, sm->is_integrated, app->use_gpu
    );

    sm->num_mom = gkyl_dg_updater_moment_num_mom(sm->mcalc);

    // Allocate arrays to hold moments.
    sm->marr = mkarr(app->use_gpu, sm->num_mom, app->local_ext.volume);
    sm->marr_host = sm->marr;
    if (app->use_gpu) {
      sm->marr_host = mkarr(false, sm->num_mom, app->local_ext.volume);
    }
  } else {
    // Create moment operator.
    if (sm->is_maxwellian_moms) {
      struct gkyl_vlasov_lte_moments_inp inp_mom = {
        .phase_grid = &gkns->grid,
        .vel_grid = &gkns->grid_vel,
        .conf_basis = &app->basis,
        .phase_basis = &gkns->basis,
        .conf_range = &app->local,
        .conf_range_ext = &app->local_ext,
        .vel_range = &gkns->local_vel,
        .phase_range = &gkns->local,
        .h_ij = gkns->g_ij,
        .h_ij_inv = gkns->gij,
        .det_h = app->gk_geom->geo_int.jacobgeo,
        .hamil = gkns->hamil,
        .model_id = gkns->model_id,
        .use_gpu = app->use_gpu,
      };
      sm->vlasov_lte_moms = gkyl_vlasov_lte_moments_inew(&inp_mom);
      sm->num_mom = 5; // (n, ux, uy, uz, T/m).
      sm->diag_jacobgeo_div_func = gk_neut_species_moment_diag_jacobgeo_div_enabled_1st_comp;
    } else {
      struct gkyl_mom_canonical_pb_auxfields can_pb_inp = {.hamil = gkns->hamil};
      sm->mcalc = gkyl_dg_updater_moment_new(
        &gkns->grid, &app->basis, &gkns->basis, &app->local, &gkns->local_vel, &gkns->local,
        gkns->model_id, &can_pb_inp, mom_type, sm->is_integrated, app->use_gpu
      );

      sm->num_mom = gkyl_dg_updater_moment_num_mom(sm->mcalc);
      sm->diag_jacobgeo_div_func = gk_neut_species_moment_diag_jacobgeo_div_enabled_all_comp;
    }

    // Allocate arrays to hold moments.
    sm->marr = mkarr(app->use_gpu, sm->num_mom * app->basis.num_basis, app->local_ext.volume);
    sm->marr_host = sm->marr;
    if (app->use_gpu) {
      sm->marr_host = mkarr(false, sm->num_mom * app->basis.num_basis, app->local_ext.volume);
    }

    // Bin Op memory for rescaling moment by inverse of Jacobian
    if (app->use_gpu) {
      sm->mem_geo = gkyl_dg_bin_op_mem_cu_dev_new(app->local.volume, app->basis.num_basis);
    } else {
      sm->mem_geo = gkyl_dg_bin_op_mem_new(app->local.volume, app->basis.num_basis);
    }
  }

  sm->calc_func = gk_neut_species_kinetic_moment_calc;
  sm->release_func = gk_neut_species_kinetic_moment_release;
}

static void
gk_neut_species_fluid_moment_calc_m0(
  const struct gk_species_moment *sm, const struct gkyl_range phase_rng,
  const struct gkyl_range conf_rng, const struct gkyl_array *fin
)
{
  gkyl_array_set_offset(sm->marr, 1.0 / sm->mass, fin, 0);
}

static void
gk_neut_species_fluid_moment_calc_m1(
  const struct gk_species_moment *sm, const struct gkyl_range phase_rng,
  const struct gkyl_range conf_rng, const struct gkyl_array *fin
)
{
  gkyl_array_set_offset(sm->marr, 1.0 / sm->mass, fin, 1 * sm->num_basis_conf);
}

static void
gk_neut_species_fluid_moment_calc_m2(
  const struct gk_species_moment *sm, const struct gkyl_range phase_rng,
  const struct gkyl_range conf_rng, const struct gkyl_array *fin
)
{
  gkyl_array_set_offset(sm->marr, 2.0 / sm->mass, fin, 4 * sm->num_basis_conf);
}

static void
gk_neut_species_fluid_moment_calc(
  const struct gk_species_moment *sm, const struct gkyl_range phase_rng,
  const struct gkyl_range conf_rng, const struct gkyl_array *fin
)
{
  if (sm->is_integrated) {
    gkyl_gk_neut_fluid_prim_vars_mass_momentum_flow_thermal_energy_advance(
      sm->nf_prim_vars, fin, sm->marr, 0
    );
  } else {
    if (sm->is_maxwellian_moms) {
      // Get LTE moments.
      gkyl_gk_neut_fluid_prim_vars_lte_advance(sm->nf_prim_vars, fin, sm->marr, 0);
    } else {
      sm->fluid_calc_M(sm, phase_rng, conf_rng, fin);
    }
  }
}

static void
gk_neut_species_fluid_moment_release(
  const struct gkyl_gyrokinetic_app *app, const struct gk_species_moment *sm
)
{
  gkyl_array_release(sm->marr);
  if (app->use_gpu) {
    gkyl_array_release(sm->marr_host);
  }

  if (sm->is_integrated) {
    gkyl_gk_neut_fluid_prim_vars_release(sm->nf_prim_vars);
  } else {
    if (sm->is_maxwellian_moms) {
      gkyl_gk_neut_fluid_prim_vars_release(sm->nf_prim_vars);
    } else {
      // Nothing to release.
    }

    // Free the weak division memory.
    gkyl_dg_bin_op_mem_release(sm->mem_geo);
  }
}

static void
gk_neut_species_fluid_moment_init(
  struct gkyl_gyrokinetic_app *app, struct gk_neut_species *gkns, struct gk_species_moment *sm,
  enum gkyl_distribution_moments mom_type, bool is_integrated
)
{
  sm->diag_jacobgeo_div_func = gk_neut_species_moment_diag_jacobgeo_div_disabled;

  // Initialize fluid neutral species moment object.
  if (sm->is_integrated) {
    sm->num_mom = 6; // rho, rho*ux, rho*uy, rho*uz, flowE, thermalE.

    // Allocate arrays to hold moments.
    sm->marr = mkarr(app->use_gpu, sm->num_mom, app->local_ext.volume);
    sm->marr_host = sm->marr;
    if (app->use_gpu) {
      sm->marr_host = mkarr(false, sm->num_mom, app->local_ext.volume);
    }

    sm->nf_prim_vars = gkyl_gk_neut_fluid_prim_vars_new(
      gkns->info.gas_gamma, gkns->info.mass, &app->basis, &app->grid, &app->local_ext,
      GKYL_GK_NEUT_FLUID_PRIM_VARS_MASS_MOMENTUM_FLOW_THERMAL_ENERGY, true, app->use_gpu
    );
  } else {
    if (sm->is_maxwellian_moms) {
      // Compute (n, ux, uy, uz, T/m) moments.
      sm->num_mom = 5;
      sm->nf_prim_vars = gkyl_gk_neut_fluid_prim_vars_new(
        gkns->info.gas_gamma, gkns->info.mass, &app->basis, &app->grid, &app->local_ext,
        GKYL_GK_NEUT_FLUID_PRIM_VARS_LTE, false, app->use_gpu
      );
      sm->diag_jacobgeo_div_func = gk_neut_species_moment_diag_jacobgeo_div_enabled_1st_comp;
    } else {
      sm->mass = gkns->info.mass;
      sm->num_basis_conf = app->basis.num_basis;

      if (mom_type == GKYL_F_MOMENT_M0) {
        sm->num_mom = 1;
        sm->fluid_calc_M = gk_neut_species_fluid_moment_calc_m0;
      } else if (mom_type == GKYL_F_MOMENT_M1) {
        sm->num_mom = 3;
        sm->fluid_calc_M = gk_neut_species_fluid_moment_calc_m1;
      } else if (mom_type == GKYL_F_MOMENT_M2) {
        sm->num_mom = 1;
        sm->fluid_calc_M = gk_neut_species_fluid_moment_calc_m2;
      } else {
        // Not yet implemented.
        assert(false);
      }

      sm->diag_jacobgeo_div_func = gk_neut_species_moment_diag_jacobgeo_div_enabled_all_comp;
    }

    // Allocate arrays to hold moments.
    sm->marr = mkarr(app->use_gpu, sm->num_mom * app->basis.num_basis, app->local_ext.volume);
    sm->marr_host = sm->marr;
    if (app->use_gpu) {
      sm->marr_host = mkarr(false, sm->marr->ncomp, sm->marr->size);
    }

    // Bin Op memory for rescaling moment by inverse of Jacobian
    if (app->use_gpu) {
      sm->mem_geo = gkyl_dg_bin_op_mem_cu_dev_new(app->local.volume, app->basis.num_basis);
    } else {
      sm->mem_geo = gkyl_dg_bin_op_mem_new(app->local.volume, app->basis.num_basis);
    }
  }

  sm->calc_func = gk_neut_species_fluid_moment_calc;
  sm->release_func = gk_neut_species_fluid_moment_release;
}

void
gk_neut_species_moment_init(
  struct gkyl_gyrokinetic_app *app, struct gk_neut_species *gkns, struct gk_species_moment *sm,
  enum gkyl_distribution_moments mom_type, bool is_integrated
)
{
  // Initialize neutral species moment object.
  sm->is_integrated = is_integrated;
  sm->is_maxwellian_moms = mom_type == GKYL_F_MOMENT_LTE;

  if (gkns->is_fluid) {
    gk_neut_species_fluid_moment_init(app, gkns, sm, mom_type, is_integrated);
  } else {
    gk_neut_species_kinetic_moment_init(app, gkns, sm, mom_type, is_integrated);
  }
}

void
gk_neut_species_moment_calc(
  const struct gk_species_moment *sm, const struct gkyl_range phase_rng,
  const struct gkyl_range conf_rng, const struct gkyl_array *fin
)
{
  sm->calc_func(sm, phase_rng, conf_rng, fin);
