    avg_dim[d] = 1; // Average all except first dimension (x).
  }
  ad->fs_avg = gkyl_array_average_inew(&(struct gkyl_array_average_inp){
    .grid = &app->grid,
    .basis = app->basis,
    .basis_avg = ad->basis_x,
    .local = &app->local,
    .local_avg = &ad->local_x,
    .local_avg_ext = &ad->local_x_ext,
