  }
  gkf->has_adiabatic_species = gkf->adiab.species_idx >= 0;
  gkf->init_adiab_func = gk_field_adiabatic_init_none;
  gkf->accumulate_rhoc_bg_func = gk_field_accumulate_rho_c_bg_none;
