      void *ctx_udrift;
      void (*udrift)(double t, const double *xn, double *fout, void *ctx);

      // Options for a Maxwellian in vel-space w/ Gaussian shape in conf-space.
      double gaussian_mean[GKYL_MAX_CDIM]; // Center in configuration space.
