        double vtsq_s = gks->info.collisions.temp_ref / mass_self;
        double vtsq_r = lbo->collide_with[i]->info.collisions.temp_ref / mass_other;

        lbo->alpha_E_fac[i] =
          (alpha_E_norm[i] * den_s * den_r / pow(sqrt(vtsq_s + vtsq_r), 3.0)) *
          pow(sqrt(2.0), app->cdim);
      }

