    if (app->use_gpu) {
      gkyl_array_release(proj->proj_host);
    }
  } else if (proj->proj_id == GKYL_PROJ_MAXWELLIAN_PRIM ||
             proj->proj_id == GKYL_PROJ_BIMAXWELLIAN) {
    gkyl_array_release(proj->dens);
    gkyl_array_release(proj->upar);
