    gkyl_array_release(proj->prim_moms);
    if (!proj->dens_from_file) {
      gkyl_proj_on_basis_release(proj->proj_dens);
    }
    if (!proj->upar_from_file) {
      gkyl_proj_on_basis_release(proj->proj_upar);
