  );
  // Methods for neutral species.
  void (*rhs_func_neut)(
    gkyl_gyrokinetic_app *app, struct gk_neut_species *gkns, struct gk_collisionless *gkcls,
    const struct gkyl_array *fin, struct gkyl_array *rhs
  );
