// Field data.
struct gk_field;

// Adiabatic species response.
struct gk_field_adiabatic {
  int species_idx; // Index of the adiabatic species.
  struct gkyl_array *kJ; // K = (q_s^2 n_s0/T_s)*J, from the t=0 moments of the species.
  struct gkyl_array *kSq; // -K, Helmholtz coefficient passed to the solver (2x/3x).
  struct gkyl_array *rho_bg; // q_s n_s0 J, background charge density.
  // Computes out = phi - <phi> (no flux-surface average in 1x).
  void (*dphi_func)(
    gkyl_gyrokinetic_app *app, const struct gk_field *gkf, const struct gkyl_array *phi,
    struct gkyl_array *out
  );

  // Adiabatic electron objects (2x/3x): flux-surface average and zonal (Woodbury) system.
  struct gkyl_array *phi2, *rhs2; // Scratch fields for the zonal response solve.
  struct gkyl_array *phi_rhs0; // Solution with rhs = 0.

  struct gkyl_basis basis_x; // 1D basis in x.
  struct gkyl_range local_x, local_x_ext; // 1D ranges in x.
  struct gkyl_array_average *fs_avg; // Flux-surface average operator.
  struct gkyl_array *jphi; // J*phi.
  struct gkyl_array *avg_jphi, *avg_jphi_red; // (y,z) average of J*phi, MPI-reduced.
  struct gkyl_array *avg_j; // Global (y,z) average of J.
  struct gkyl_array *psi, *psi_ho; // Flux-surface averaged potential (1D in x).
  gkyl_dg_bin_op_mem *div_mem; // Memory for the 1D weak division.

  struct gkyl_range local_xy, local_xy_ext; // 2D (x,y) ranges (3x only).
  struct gkyl_array *tmp_xy; // 2D scratch for the 1D->3D extension (3x only).
  struct gkyl_translate_dim *inflate_lo, *inflate_up; // 1D->2D and 2D->3D extension updaters.

  int num_zonal; // m = Nx*num_basis_x zonal degrees of freedom.
  struct gkyl_mat *A; // I - G.
  struct gkyl_mat *A_lu; // Work copy of A, LU factored at each solve.
  struct gkyl_mat *rhs_m; // m x 1 work vector.
  gkyl_mem_buff ipiv; // Pivots for the LU solve.

  struct gkyl_array_integrate *calc_energy; // Computes int K (phi-<phi>)^2.
  double *energy_red; // Memory for the energy reduction.
};

struct gk_field {
  struct gkyl_gyrokinetic_field info; // Data for field.

  enum gkyl_gkfield_id gkfield_id; // Field solver ID.
  enum gkyl_gyrokinetic_bc_type bc_par_phi; // Parallel BC to enforce on phi.

  bool update_field; // Are we updating the field?.
  bool calc_init_field; // Whether to compute the t=0 field.

  // Arrays for local charge density, global charge density, and global smoothed (in z) charge density.
  struct gkyl_array *rho_c;
  struct gkyl_array *rho_c_global_dg;
  struct gkyl_array *rho_c_global_smooth;
  struct gkyl_array *phi_fem, *phi_smooth; // Arrays for updates.

  struct gkyl_array *phi_host; // host copy for use IO and initialization

  bool init_phi_pol; // Whether to use the initial user polarization phi.
  struct gkyl_array *phi_pol; // Initial polarization density potential.

  struct gkyl_range global_sub_range; // sub range of intersection of global range and local range
  // for solving subset of Poisson solves with parallelization in z

  // organization of the different equation objects and the required data and solvers
  union {
    struct {
      struct gkyl_ambi_bolt_potential *ambi_pot;
      struct gkyl_array *sheath_vals[2 * GKYL_MAX_CDIM];
    };
    // EM GK model
    struct {
      struct gkyl_array *apar_fem; // array for A_parallel
      struct gkyl_array *apardot_fem; // array for d/dt A_parallel
    };
  };

  double es_energy_fac_1d;
  struct gkyl_array *es_energy_fac;
  bool is_dirichletvar; // Whether user provided spatially varying phi BCs.
  struct gkyl_array *phi_bc; // Spatially varying BC.
  struct gkyl_array *epsilon; // Polarization weight including geometric factors.
  bool has_adiabatic_species; // Whether a species has an adiabatic response.
  struct gkyl_poisson_bc poisson_bcs; // Perpendicular Poisson BCs (2x/3x).
  struct gk_field_adiabatic adiab; // Adiabatic species response.
  int num_rhoc_species; // Number of species whose charge density enters rho_c.
  int rhoc_species_idx[GKYL_MAX_SPECIES]; // Indices of the species whose charge enters rho_c.

  struct gkyl_poisson_bias_line_list
    fem_parproj_bias_line_list; // Biased lines constraining the solution.

  struct gkyl_fem_parproj
    *fem_parproj; // Projects DG function onto continuous  FEM basis:  weight*phi_{fem} = phi_{dg}
  struct gkyl_fem_parproj *fem_parproj_rho_sol, *fem_parproj_phi_sol; // FEM projection in the SOL.
  struct gkyl_fem_parproj *fem_parproj_rho_core,
    *fem_parproj_phi_core; // FEM projection in the core.

  struct gkyl_fem_poisson_perp
    *fem_poisson_perp; // Solves - nabla . (epsilon * nabla phi) - kSq * phi = rho.

  // Objects needed for FLR effects.
  bool use_flr; // Whether to apply FLR effects.
  void (*invert_flr)(
    gkyl_gyrokinetic_app *app, struct gk_field *field,
    struct gkyl_array *phi
  ); // Function inverting  FLR  operator.
  struct gkyl_array *flr_rhoSq_sum; // Laplacian weight in FLR operator.
  struct gkyl_array *flr_kSq; // Field multiplying phi in FLR operator.
  struct gkyl_deflated_fem_poisson *flr_op; // Helmholtz solver to invert FLR operator.

  struct gkyl_array_integrate *calc_em_energy; // Operator computing EM energy.
  double *em_energy_red, *em_energy_red_global; // memory for use in GPU reduction of EM energy
  gkyl_dynvec integ_energy; // integrated energy components
  bool is_first_energy_write_call; // flag for energy dynvec written first time

  double *em_energy_red_old,
    *em_energy_red_new; // memory for use in GPU reduction of old EM energy.
  gkyl_dynvec integ_energy_dot; // d/dt of integrated energy components.
  bool is_first_energy_dot_write_call; // flag for d(energy)/dt dynvec written first time

  bool has_phi_wall_lo; // flag to indicate there is biased wall potential on lower wall
  bool phi_wall_lo_evolve; // flag to indicate biased wall potential on lower wall is time dependent
  struct gkyl_array *phi_wall_lo; // biased wall potential on lower wall
  struct gkyl_array *phi_wall_lo_host; // host copy for use in IO and projecting
  gkyl_eval_on_nodes *phi_wall_lo_proj; // projector for biased wall potential on lower wall

  bool has_phi_wall_up; // flag to indicate there is biased wall potential on upper wall
  bool phi_wall_up_evolve; // flag to indicate biased wall potential on upper wall is time dependent
  struct gkyl_array *phi_wall_up; // biased wall potential on upper wall
  struct gkyl_array *phi_wall_up_host; // host copy for use in IO and projecting
  gkyl_eval_on_nodes *phi_wall_up_proj; // projector for biased wall potential on upper wall

  // Pointer to function that computes the time rate of change of the energy.
  void (*calc_energy_dt_func)(
    gkyl_gyrokinetic_app *app, const struct gk_field *field, double dt, double *energy_reduced
  );

  // Objects used in IWL simulations and TS BCs.
  struct gkyl_rect_grid bc_ts_grid; // Higher resolution grid for TS BC.
  struct gkyl_range bc_ts_global_ext, bc_ts_global; // Higher resolution ranges for TS BC.
  struct gkyl_range bc_ts_global_lower_skin_par,
    bc_ts_global_upper_skin_par; // Parallel skin for TS BC.
  struct gkyl_range bc_ts_global_lower_ghost_par,
    bc_ts_global_upper_ghost_par; // Parallel ghost for TS BC.
  struct gkyl_dg_interpolate *bc_ts_prolong, *bc_ts_coarsen; // Interpolation operators for TS BC.
  struct gkyl_array *bc_ts_buffer_fine, *bc_ts_buffer_coar; // Buffer for TS BCs.
  struct gkyl_range bc_ts_global_par_ext; // Range extended in parallel direction for TS BC.
  struct gkyl_bc_twistshift *bc_ts_lo, *bc_ts_up; // Fills z-ghosts with TS BC.
  struct gkyl_bc_basic_gyrokinetic
    *gfss_bc_op_core_up; // Fills upper core  z-ghost with skin  boundary value.
  struct gkyl_bc_basic_gyrokinetic
    *gfss_bc_op_core_lo; // Fills lower core  z-ghost with skin  boundary value.
  struct gkyl_array *bc_buffer; // Buffer for bc_basic.

  // Pointer to functions that make phi continuous along z.
  void (*fem_projection_par_rho_func)(
    gkyl_gyrokinetic_app *app, struct gk_field *field, struct gkyl_array *arr_dg,
    struct gkyl_array *arr_fem
  );
  void (*fem_projection_par_phi_func)(
    gkyl_gyrokinetic_app *app, struct gk_field *field, struct gkyl_array *arr_dg,
    struct gkyl_array *arr_fem
  );
  // Pointer to function to calculate the potential.
  void (*rhs_phi_func)(struct gkyl_gyrokinetic_app *app, struct gk_field *field);
  // Pointer to function that calculates the field energy.
  void (*calc_energy_func)(gkyl_gyrokinetic_app *app, const struct gk_field *field, double tm);
  // Pointer to function that accumulates the charge density.
  void (*accumulate_rhoc_func)(
    gkyl_gyrokinetic_app *app, struct gk_field *field, struct gk_species *gks,
    struct gkyl_array **bflux
  );
  // Pointer to function that sets up the adiabatic response from the t=0 species moments.
  void (*init_adiab_func)(gkyl_gyrokinetic_app *app, struct gk_field *field);
  // Pointer to function that adds a background charge density (e.g. of an adiabatic species).
  void (*accumulate_rhoc_bg_func)(gkyl_gyrokinetic_app *app, struct gk_field *field);
  // Pointer to function that adds the adiabatic species energy, factor*(1/2) int K (phi-<phi>)^2.
  void (*energy_adiab_func)(
    gkyl_gyrokinetic_app *app, const struct gk_field *field, double factor, double *out
  );
  // Pointer to function that frees memory.
  void (*release_func)(const struct gkyl_gyrokinetic_app *app, struct gk_field *field);
};

