 */
void gk_species_radiation_rhs(
  gkyl_gyrokinetic_app *app, const struct gk_species *species, struct gk_rad_drag *rad,
  const struct gkyl_array *fin, struct gkyl_array *rhs
);

/**
 * Write species radiation drag.
