static void
gk_species_projection_from_moms_kinetic(gkyl_gyrokinetic_app *app, struct gk_species *gks,
  struct gk_proj *proj, struct gkyl_array *f, double tm)
{
  gkyl_gk_maxwellian_proj_on_basis_advance(
    proj->proj_max, &gks->local, &app->local, proj->prim_moms, false, f);
}

static void
gk_species_projection_from_moms_fluid(gkyl_gyrokinetic_app *app, struct gk_species *gks,
  struct gk_proj *proj, struct gkyl_array *f, double tm)
{
  int nb = app->basis.num_basis;
  gkyl_array_clear(f, 0.0);
  // Copy the first three primitive fields, then supply the perpendicular temperature.
  for (int c = 0; c < 3; ++c) {
    gkyl_array_set_offset_range(proj->dens, 1.0, proj->prim_moms_host, c*nb, &app->local);
    gkyl_array_set_offset_range(proj->prim_moms_host, 1.0, proj->dens, c*nb, &app->local);
  }
  // Host staging has four components for fluids, including isotropic projections.
  if (proj->proj_id == GKYL_PROJ_MAXWELLIAN_PRIM) {
    gkyl_array_set_offset_range(proj->dens, 1.0, proj->prim_moms_host, 2*nb, &app->local);
    gkyl_array_set_offset_range(proj->prim_moms_host, 1.0, proj->dens, 3*nb, &app->local);
  }
  if (gks->info.vdim == 1)
    gkyl_array_clear_range(proj->dens, 0.0, &app->local);
  if (gks->info.vdim == 1)
    gkyl_array_set_offset_range(proj->prim_moms_host, 1.0, proj->dens, 3*nb, &app->local);
  gkyl_array_copy(f, proj->prim_moms_host);
}
