const moved=new Set(["gk_species_omegaH_dt","gk_species_rhs_dynamic","gk_species_rhs_implicit_dynamic","gk_species_apply_bc_dynamic","gk_species_release_dynamic","gk_species_init_dynamic","gk_species_file_import_init","gk_species_do_I_recycle","gk_species_do_I_recycle_react_scale","gk_species_do_I_adapt_src","gk_species_init","gk_species_release"]);
let common="#include <gkyl_gk_species_priv.h>\n\n",kinetic=common;
let init=funcs.find(f=>f.name==="gk_species_init").text;
const ia=init.indexOf("  // Species properties metadata."),ib=init.indexOf("  // Allocate distribution function arrays.",ia);
const meta=init.slice(ia,ib);
const dyn=funcs.find(f=>f.name==="gk_species_init_dynamic").text;
const da=dyn.indexOf("  // Allocate data for integrated moments."),db=dyn.indexOf("  // Objects for L2 norm diagnostic.",da);
const intinit=dyn.slice(da,db);
const rel=funcs.find(f=>f.name==="gk_species_release_dynamic").text;
const ra=rel.indexOf("  // Release integrated moment memory."),rb=rel.indexOf("  // Release L2 norm memory.",ra);
const intrelease=rel.slice(ra,rb);
const fdotrel=`  if (gks->info.time_rate_diagnostics) {
    // Free df/dt diagnostics memory.
    gkyl_array_release(gks->fdot_mom_old);
    gkyl_array_release(gks->fdot_mom_new);
    gkyl_dynvec_release(gks->fdot_integ_diag);
  }
`;
let helpers=[
`void\ngk_species_init_io(struct gkyl_gyrokinetic_app *app, struct gk_species *gks)\n{\n${meta}}\n`,
`void\ngk_species_init_integrated_mom(struct gkyl_gyrokinetic_app *app, struct gk_species *gks)\n{\n${intinit}}\n`,
`void\ngk_species_release_integrated_mom(const struct gkyl_gyrokinetic_app *app, const struct gk_species *gks)\n{\n${intrelease}${fdotrel}}\n`
];
const commonDefs=[];
for (const f of funcs) {
 let s=f.text;
 if(moved.has(f.name)) {
   if(f.name==="gk_species_init") s=s.replace("gk_species_init(","gk_species_kinetic_init(").replace(meta,"  gk_species_init_io(app, gks);\n\n").replace("{\n", "{\n  gks->release_species_func = gk_species_kinetic_release;\n");
   if(f.name==="gk_species_release") s=s.replace("gk_species_release(","gk_species_kinetic_release(");
   if(f.name==="gk_species_init_dynamic") s=s.replace(intinit,"  gk_species_init_integrated_mom(app, gks);\n\n");
   if(f.name==="gk_species_release_dynamic") s=s.replace(intrelease,"  gk_species_release_integrated_mom(app, gks);\n\n").replace(fdotrel,"");
   kinetic+=s+"\n";
 } else {
   // Shared callbacks are declared in the species-private header.
   s=s.replace(/^static /,"");
   commonDefs.push(s);
   common+=s+"\n";
 }
}
common+=helpers.join("\n");
common+=`
void
gk_species_init(struct gkyl_gk *inp, struct gkyl_gyrokinetic_app *app, struct gk_species *gks)
{
  struct gkyl_gyrokinetic_species info = gks->info;
  memset(gks, 0, sizeof *gks);
  gks->info = info;
  gks->is_fluid = info.cells[0] == 0;
  if (gks->is_fluid) gk_species_fluid_init(inp, app, gks);
  else gk_species_kinetic_init(inp, app, gks);
}

void
gk_species_release(const gkyl_gyrokinetic_app *app, const struct gk_species *gks)
{
  gks->release_species_func(app, gks);
}
`;
