  struct timespec wst = gkyl_wall_clock();
  gk_species_moment_calc(&lbo->moms, species->local, app->local, fin);
  gkyl_array_set_offset_range(lbo->m2self, 1.0, lbo->moms.marr,
    2*app->basis.num_basis, &app->local);
  gk_species_moment_calc(&species->lte.moms, species->local, app->local, fin);
  gkyl_array_set_offset_range(lbo->prim_moms, 1.0, species->lte.moms.marr,
    app->basis.num_basis, &app->local);
  lbo->self_nu_func(app, species, lbo, fin);
  for (int d = 0; d < 2; ++d)
    gkyl_dg_mul_op_range(&app->basis, d, lbo->nu_prim_moms, d, lbo->prim_moms,
      0, lbo->self_nu, &app->local);
  app->stat.species_coll_mom_tm += gkyl_time_diff_now_sec(wst);
}

