#include <assert.h>
#include <gkyl_gyrokinetic_priv.h>
#include <gkyl_gk_fluid_moments.h>

static void
gk_species_moment_diag_jacobgeo_div_disabled(
  const struct gkyl_gyrokinetic_app *app, struct gk_species_moment *sm, struct gkyl_array *Jmom_in,
  struct gkyl_array *mom_out
)
{
  // Do nothing.
}

static void
gk_species_moment_diag_jacobgeo_div_enabled_1st_comp(
  const struct gkyl_gyrokinetic_app *app, struct gk_species_moment *sm, struct gkyl_array *Jmom_in,
  struct gkyl_array *mom_out
)
{
  // Only divide the first component.
  gkyl_dg_div_op_range(
    sm->mem_geo, &app->basis, 0, mom_out, 0, Jmom_in, 0, app->gk_geom->geo_int.jacobgeo, &app->local
  );
}

static void
gk_species_moment_diag_jacobgeo_div_enabled_all_comp(
  const struct gkyl_gyrokinetic_app *app, struct gk_species_moment *sm, struct gkyl_array *Jmom_in,
  struct gkyl_array *mom_out
)
{
  // Divide all components.
  for (int k = 0; k < sm->num_mom; k++) {
    gkyl_dg_div_op_range(
      sm->mem_geo, &app->basis, k, mom_out, k, Jmom_in, 0, app->gk_geom->geo_int.jacobgeo,
      &app->local
    );
  }
}


static void gk_species_moment_calc_kinetic(const struct gk_species_moment *,
  const struct gkyl_range, const struct gkyl_range, const struct gkyl_array *);
static void gk_species_moment_release_kinetic(const struct gkyl_gyrokinetic_app *,
  const struct gk_species_moment *);

static void
gk_species_moment_calc_fluid(const struct gk_species_moment *sm,
  const struct gkyl_range species_rng, const struct gkyl_range conf_rng,
  const struct gkyl_array *fin)
{
  gkyl_gk_fluid_moments_advance(sm->gf_moms, &conf_rng, fin, sm->fluid_phi, sm->marr);
}

static void
gk_species_moment_release_fluid(const struct gkyl_gyrokinetic_app *app,
  const struct gk_species_moment *sm)
{
  gkyl_gk_fluid_moments_release(sm->gf_moms);
  gkyl_array_release(sm->marr);
  if (app->use_gpu) gkyl_array_release(sm->marr_host);
  if (!sm->is_integrated) gkyl_dg_bin_op_mem_release(sm->mem_geo);
}

static void
gk_species_moment_init_fluid(struct gkyl_gyrokinetic_app *app,
  struct gk_species *gks, struct gk_species_moment *sm,
  enum gkyl_distribution_moments mom_type)
{
  sm->gf_moms = gkyl_gk_fluid_moments_new(&app->basis, &app->grid, gks->info.vdim,
    gks->info.mass, gks->info.charge, mom_type, sm->is_integrated, app->use_gpu);
  sm->fluid_phi = app->field->phi_smooth;
  sm->num_mom = gkyl_gk_fluid_moments_num_mom(sm->gf_moms);
  sm->marr = mkarr(app->use_gpu, sm->num_mom*(sm->is_integrated ? 1 : app->basis.num_basis),
    app->local_ext.volume);
  sm->marr_host = app->use_gpu ? mkarr(false, sm->marr->ncomp, sm->marr->size) : sm->marr;
  if (!sm->is_integrated) {
    sm->mem_geo = app->use_gpu ?
      gkyl_dg_bin_op_mem_cu_dev_new(app->local.volume, app->basis.num_basis) :
      gkyl_dg_bin_op_mem_new(app->local.volume, app->basis.num_basis);
    sm->diag_jacobgeo_div_func = sm->is_maxwellian_moms || sm->is_bimaxwellian_moms ?
      gk_species_moment_diag_jacobgeo_div_enabled_1st_comp :
      gk_species_moment_diag_jacobgeo_div_enabled_all_comp;
  }
  sm->calc_func = gk_species_moment_calc_fluid;
  sm->release_func = gk_species_moment_release_fluid;
}

void
gk_species_moment_init(
  struct gkyl_gyrokinetic_app *app, struct gk_species *gks, struct gk_species_moment *sm,
  enum gkyl_distribution_moments mom_type, bool is_integrated
)
{
  sm->is_integrated = is_integrated;
  sm->is_maxwellian_moms = mom_type == GKYL_F_MOMENT_MAXWELLIAN;
  sm->is_bimaxwellian_moms = mom_type == GKYL_F_MOMENT_BIMAXWELLIAN;
  sm->diag_jacobgeo_div_func = gk_species_moment_diag_jacobgeo_div_disabled;

  if (gks->is_fluid) {
    gk_species_moment_init_fluid(app, gks, sm, mom_type);
    return;
  }
  sm->calc_func = gk_species_moment_calc_kinetic;
  sm->release_func = gk_species_moment_release_kinetic;

  if (sm->is_integrated) {
    // Create moment operator.
    sm->mcalc = gkyl_dg_updater_moment_gyrokinetic_new(
      &gks->grid, &app->basis, &gks->basis, &app->local_ext, gks->info.mass, gks->info.charge,
      gks->vel_map, app->gk_geom, app->field->phi_smooth, mom_type, sm->is_integrated, app->use_gpu
    );

    sm->num_mom = gkyl_dg_updater_moment_gyrokinetic_num_mom(sm->mcalc);

    // Allocate arrays to hold moments.
    sm->marr = mkarr(app->use_gpu, sm->num_mom, app->local_ext.volume);
    sm->marr_host = sm->marr;
    if (app->use_gpu) {
      sm->marr_host = mkarr(false, sm->num_mom, app->local_ext.volume);
    }
  } else {
    // Create moment operator.
    if (sm->is_maxwellian_moms || sm->is_bimaxwellian_moms) {
      struct gkyl_gk_maxwellian_moments_inp inp_mom = {
        .phase_grid = &gks->grid,
        .conf_basis = &app->basis,
        .phase_basis = &gks->basis,
        .conf_range = &app->local,
        .conf_range_ext = &app->local_ext,
        .gk_geom = app->gk_geom,
        .vel_map = gks->vel_map,
        .divide_jacobgeo = false,
        .mass = gks->info.mass,
        .use_gpu = app->use_gpu,
      };
      sm->gyrokinetic_maxwellian_moms = gkyl_gk_maxwellian_moments_inew(&inp_mom);
      if (sm->is_maxwellian_moms) {
        sm->num_mom = 3; // (n, u_par, T/m)
      } else {
#include <assert.h>
#include <gkyl_alloc.h>
#include <gkyl_gauss_quad_data.h>
#include <gkyl_gk_fluid_moments_priv.h>

struct gkyl_gk_fluid_moments *
gkyl_gk_fluid_moments_new(const struct gkyl_basis *basis,
  const struct gkyl_rect_grid *grid, int vdim, double mass, double charge,
  enum gkyl_distribution_moments moment, bool integrated, bool use_gpu)
{
  assert(vdim == 1 || vdim == 2);
  struct gkyl_gk_fluid_moments *up = gkyl_malloc(sizeof *up);
  *up = (struct gkyl_gk_fluid_moments) {
    .num_basis = basis->num_basis, .vdim = vdim, .mass = mass, .charge = charge,
    .moment = moment, .integrated = integrated, .use_gpu = use_gpu, .cell_factor = 1.0
  };
  switch (moment) {
    case GKYL_F_MOMENT_M0: case GKYL_F_MOMENT_M1: case GKYL_F_MOMENT_M2:
    case GKYL_F_MOMENT_M2PAR: case GKYL_F_MOMENT_M2PERP:
    case GKYL_F_MOMENT_M3PAR: case GKYL_F_MOMENT_M3PERP: up->num_mom = 1; break;
    case GKYL_F_MOMENT_MAXWELLIAN: case GKYL_F_MOMENT_M0M1M2:
    case GKYL_F_MOMENT_HAMILTONIAN: up->num_mom = 3; break;
    case GKYL_F_MOMENT_BIMAXWELLIAN: up->num_mom = 4; break;
    case GKYL_F_MOMENT_M0M1M2PARM2PERP: up->num_mom = vdim+2; break;
    default: gkyl_exit("Unsupported gyrokinetic fluid moment.");
  }
  // Jn*u^3 times a test function has degree 5*p in each coordinate.
  int nq = (5*basis->poly_order+2)/2;
  if (nq < 1) nq = 1;
  double ordinates[nq], weights[nq];
  if (nq <= gkyl_gauss_max) {
    for (int q = 0; q < nq; ++q) {
      ordinates[q] = gkyl_gauss_ordinates[nq][q];
      weights[q] = gkyl_gauss_weights[nq][q];
    }
  } else gkyl_gauleg(-1.0, 1.0, ordinates, weights, nq);
  int shape[GKYL_MAX_CDIM];
  for (int d = 0; d < grid->ndim; ++d) {
    shape[d] = nq;
    up->cell_factor *= 0.5*grid->dx[d];
  }
  struct gkyl_range qr;
  gkyl_range_init_from_shape(&qr, grid->ndim, shape);
  up->num_quad = qr.volume;
  struct gkyl_array *quad = gkyl_array_new(GKYL_DOUBLE, basis->num_basis+1, qr.volume);
  struct gkyl_range_iter iter;
  gkyl_range_iter_init(&iter, &qr);
  while (gkyl_range_iter_next(&iter)) {
    double xn[GKYL_MAX_CDIM], weight = 1.0;
    for (int d = 0; d < grid->ndim; ++d) {
      int q = iter.idx[d]-qr.lower[d];
      xn[d] = ordinates[q]; weight *= weights[q];
    }
    double *data = gkyl_array_fetch(quad, gkyl_range_idx(&qr, iter.idx));
    basis->eval(xn, data);
    data[basis->num_basis] = weight;
  }
  up->quad = quad;
  if (use_gpu) {
    up->quad = gkyl_array_cu_dev_new(GKYL_DOUBLE, quad->ncomp, quad->size);
    gkyl_array_copy(up->quad, quad);
    gkyl_array_release(quad);
  }
  return up;
}

int
gkyl_gk_fluid_moments_num_mom(const struct gkyl_gk_fluid_moments *up)
{
  return up->num_mom;
}

void
gkyl_gk_fluid_moments_advance(const struct gkyl_gk_fluid_moments *up,
  const struct gkyl_range *range, const struct gkyl_array *state,
  const struct gkyl_array *phi, struct gkyl_array *out)
{
#ifdef GKYL_HAVE_CUDA
  if (up->use_gpu) {
    gkyl_gk_fluid_moments_advance_cu(up, range, state, phi, out);
    return;
  }
#endif
  struct gkyl_range_iter iter;
  gkyl_range_iter_init(&iter, range);
  while (gkyl_range_iter_next(&iter)) {
    long loc = gkyl_range_idx(range, iter.idx);
    gk_fluid_moments_cell(up, gkyl_array_cfetch(state, loc),
      phi ? gkyl_array_cfetch(phi, loc) : 0, up->quad, gkyl_array_fetch(out, loc));
  }
}

void
gkyl_gk_fluid_moments_release(struct gkyl_gk_fluid_moments *up)
{
  gkyl_array_release(up->quad);
  gkyl_free(up);
}
