  sca->write_func = gk_species_scaling_write_disabled;

  if (sca_inp->type == GKYL_GK_SPECIES_SCALING_FIXED_FRACTION) {
    sca->type = sca_inp->type;
    sca->write_diagnostics = sca_inp->write_diagnostics;

