  } else if (sca_inp->type == GKYL_GK_SPECIES_SCALING_ADIABATIC) {
    sca->type = sca_inp->type;
    sca->dens_adiab = mkarr(app->use_gpu, app->basis.num_basis, app->local_ext.volume);
