  gkyl_dg_div_op_range(gks->m0.mem_geo, &app->basis, 0, density, 0, density,
    0, gks->m0.marr, &app->local);
  gkyl_dg_mul_conf_phase_op_range(&app->basis, &gks->basis, fin, density, fin,
    &app->local, &gks->local);
}

