#include <assert.h>
#include <stdlib.h>
#include <string.h>

#include <gkyl_alloc.h>
#include <gkyl_alloc_flags_priv.h>
#include <gkyl_util.h>
#include <gkyl_prim_lbo_gyrokinetic.h>
#include <gkyl_prim_lbo_gyrokinetic_priv.h>

void
prim_lbo_gyrokinetic_free(const struct gkyl_ref_count *ref)
{
  struct gkyl_prim_lbo_type *prim_ty = container_of(ref, struct gkyl_prim_lbo_type, ref_count);
  if (GKYL_IS_CU_ALLOC(prim_ty->flag)) {
    gkyl_cu_free(prim_ty->on_dev);
  }

  struct prim_lbo_type_gyrokinetic *gk =
    container_of(prim_ty, struct prim_lbo_type_gyrokinetic, prim);
  gkyl_free(gk);
}

struct gkyl_prim_lbo_type *
gkyl_prim_lbo_gyrokinetic_new_with_vdim(
  const struct gkyl_basis *cbasis, int vdim, int num_phase, bool use_gpu
)
{

#ifdef GKYL_HAVE_CUDA
  if (use_gpu) {
    return gkyl_prim_lbo_gyrokinetic_cu_dev_new_with_vdim(cbasis, vdim, num_phase);
  }
#endif
  struct prim_lbo_type_gyrokinetic *prim_gyrokinetic =
    gkyl_malloc(sizeof(struct prim_lbo_type_gyrokinetic));
  int cdim = prim_gyrokinetic->prim.cdim = cbasis->ndim;
  int pdim = prim_gyrokinetic->prim.pdim = cdim + vdim;
  int poly_order = prim_gyrokinetic->prim.poly_order = cbasis->poly_order;
  prim_gyrokinetic->prim.num_config = cbasis->num_basis;
  prim_gyrokinetic->prim.num_phase = num_phase;
  prim_gyrokinetic->prim.self_prim = self_prim;
  prim_gyrokinetic->prim.cross_prim = cross_prim;
  prim_gyrokinetic->prim.udim = 1;

  // choose kernel tables based on basis-function type
  const gkyl_prim_lbo_gyrokinetic_kern_list *self_prim_kernels;
  const gkyl_prim_lbo_gyrokinetic_cross_kern_list *cross_prim_kernels;

  switch (cbasis->b_type) {
    case GKYL_BASIS_MODAL_SERENDIPITY:
      self_prim_kernels = ser_self_prim_kernels;
      cross_prim_kernels = ser_cross_prim_kernels;
      break;

    default:
      assert(false);
      break;
  }
  assert(NULL != self_prim_kernels[pdim - 2].kernels[poly_order]);
  assert(NULL != cross_prim_kernels[pdim - 2].kernels[poly_order]);

  prim_gyrokinetic->self_prim = self_prim_kernels[pdim - 2].kernels[poly_order];
  prim_gyrokinetic->cross_prim = cross_prim_kernels[pdim - 2].kernels[poly_order];

  prim_gyrokinetic->prim.flag = 0;
  GKYL_CLEAR_CU_ALLOC(prim_gyrokinetic->prim.flag);
  prim_gyrokinetic->prim.ref_count = gkyl_ref_count_init(prim_lbo_gyrokinetic_free);

  prim_gyrokinetic->prim.on_dev = &prim_gyrokinetic->prim;

  return &prim_gyrokinetic->prim;
}

struct gkyl_prim_lbo_type *
gkyl_prim_lbo_gyrokinetic_new(
  const struct gkyl_basis *cbasis, const struct gkyl_basis *pbasis, bool use_gpu
)
{
  assert(cbasis->poly_order == pbasis->poly_order);
  return gkyl_prim_lbo_gyrokinetic_new_with_vdim(cbasis, pbasis->ndim-cbasis->ndim, pbasis->num_basis, use_gpu);
}
extern "C" {
#include <gkyl_gk_fluid_moments_priv.h>
}

__global__ static void
gk_fluid_moments_kernel(struct gkyl_gk_fluid_moments up, struct gkyl_range range,
  const struct gkyl_array *state, const struct gkyl_array *phi, struct gkyl_array *out)
{
  int idx[GKYL_MAX_DIM];
  for (long cell = threadIdx.x+blockIdx.x*blockDim.x; cell < range.volume;
       cell += gridDim.x*blockDim.x) {
    gkyl_sub_range_inv_idx(&range, cell, idx);
    long loc = gkyl_range_idx(&range, idx);
    gk_fluid_moments_cell(&up, (const double *) gkyl_array_cfetch(state, loc),
      phi ? (const double *) gkyl_array_cfetch(phi, loc) : 0, up.quad,
      (double *) gkyl_array_fetch(out, loc));
  }
}

void
gkyl_gk_fluid_moments_advance_cu(const struct gkyl_gk_fluid_moments *up,
  const struct gkyl_range *range, const struct gkyl_array *state,
  const struct gkyl_array *phi, struct gkyl_array *out)
{
  struct gkyl_gk_fluid_moments device = *up;
  device.quad = up->quad->on_dev;
  gk_fluid_moments_kernel<<<range->nblocks, range->nthreads>>>(device, *range,
    state->on_dev, phi ? phi->on_dev : 0, out->on_dev);
}

