    // Multiply moments by the conf-space Jacobian.
    for (int d = 0; d < gkns->num_moments; d++) {
      gkyl_dg_mul_op_range(&app->basis, d, f, 0, app->gk_geom->geo_int.jacobgeo, d, f, &app->local);
    }
  }
