        moments[0] = dens;
        moments[1] = m1;
        moments[2] = m2par + m2perp;
        break;
      case GKYL_F_MOMENT_M0M1M2PARM2PERP:
        moments[0] = dens;
        moments[1] = m1;
        moments[2] = m2par;
        moments[3] = m2perp;
        break;
      case GKYL_F_MOMENT_HAMILTONIAN:
        moments[0] = dens;
        moments[1] = up->mass * m1;
