#include <assert.h>
#include <gkyl_alloc.h>
#include <gkyl_gauss_quad_data.h>
#include <gkyl_gk_fluid_moments_priv.h>

struct gkyl_gk_fluid_moments *
gkyl_gk_fluid_moments_new(
  const struct gkyl_basis *basis, const struct gkyl_rect_grid *grid, int vdim, double mass,
  double charge, enum gkyl_distribution_moments moment, bool integrated, bool use_gpu
)
{
  assert(vdim == 1 || vdim == 2);
  struct gkyl_gk_fluid_moments *up = gkyl_malloc(sizeof *up);
  *up = (struct gkyl_gk_fluid_moments){
    .num_basis = basis->num_basis,
    .vdim = vdim,
    .mass = mass,
    .charge = charge,
    .moment = moment,
    .integrated = integrated,
    .use_gpu = use_gpu,
    .cell_factor = 1.0,
  };
  switch (moment) {
    case GKYL_F_MOMENT_M0:
    case GKYL_F_MOMENT_M1:
    case GKYL_F_MOMENT_M2:
    case GKYL_F_MOMENT_M2PAR:
    case GKYL_F_MOMENT_M2PERP:
    case GKYL_F_MOMENT_M3PAR:
    case GKYL_F_MOMENT_M3PERP:
      up->num_mom = 1;
      break;
    case GKYL_F_MOMENT_MAXWELLIAN:
    case GKYL_F_MOMENT_M0M1M2:
    case GKYL_F_MOMENT_HAMILTONIAN:
      up->num_mom = 3;
      break;
    case GKYL_F_MOMENT_BIMAXWELLIAN:
      up->num_mom = 4;
      break;
    case GKYL_F_MOMENT_M0M1M2PARM2PERP:
      up->num_mom = vdim + 2;
      break;
    default:
      gkyl_exit("Unsupported gyrokinetic fluid moment.");
  }
  // Jn*u^3 times a test function has degree 5*p in each coordinate.
  int nq = (5 * basis->poly_order + 2) / 2;
  if (nq < 1) {
    nq = 1;
  }
  double ordinates[nq], weights[nq];
  if (nq <= gkyl_gauss_max) {
    for (int q = 0; q < nq; ++q) {
      ordinates[q] = gkyl_gauss_ordinates[nq][q];
      weights[q] = gkyl_gauss_weights[nq][q];
    }
  } else {
    gkyl_gauleg(-1.0, 1.0, ordinates, weights, nq);
  }
  int shape[GKYL_MAX_CDIM];
  for (int d = 0; d < grid->ndim; ++d) {
    shape[d] = nq;
    up->cell_factor *= 0.5 * grid->dx[d];
  }
  struct gkyl_range qr;
  gkyl_range_init_from_shape(&qr, grid->ndim, shape);
  up->num_quad = qr.volume;
  struct gkyl_array *quad = gkyl_array_new(GKYL_DOUBLE, basis->num_basis + 1, qr.volume);
  struct gkyl_range_iter iter;
  gkyl_range_iter_init(&iter, &qr);
  while (gkyl_range_iter_next(&iter)) {
    double xn[GKYL_MAX_CDIM], weight = 1.0;
    for (int d = 0; d < grid->ndim; ++d) {
      int q = iter.idx[d] - qr.lower[d];
      xn[d] = ordinates[q];
      weight *= weights[q];
    }
    double *data = gkyl_array_fetch(quad, gkyl_range_idx(&qr, iter.idx));
    basis->eval(xn, data);
    data[basis->num_basis] = weight;
  }
  up->quad = quad;
  if (use_gpu) {
    up->quad = gkyl_array_cu_dev_new(GKYL_DOUBLE, quad->ncomp, quad->size);
    gkyl_array_copy(up->quad, quad);
    gkyl_array_release(quad);
  }
  return up;
}

int
gkyl_gk_fluid_moments_num_mom(const struct gkyl_gk_fluid_moments *up)
{
  return up->num_mom;
}

void
gkyl_gk_fluid_moments_advance(
  const struct gkyl_gk_fluid_moments *up, const struct gkyl_range *range,
  const struct gkyl_array *state, const struct gkyl_array *phi, struct gkyl_array *out
)
{
#ifdef GKYL_HAVE_CUDA
  if (up->use_gpu) {
    gkyl_gk_fluid_moments_advance_cu(up, range, state, phi, out);
    return;
  }
#endif
  struct gkyl_range_iter iter;
  gkyl_range_iter_init(&iter, range);
  while (gkyl_range_iter_next(&iter)) {
    long loc = gkyl_range_idx(range, iter.idx);
    gk_fluid_moments_cell(
      up, gkyl_array_cfetch(state, loc), phi ? gkyl_array_cfetch(phi, loc) : 0, up->quad,
      gkyl_array_fetch(out, loc)
    );
  }
}

void
gkyl_gk_fluid_moments_release(struct gkyl_gk_fluid_moments *up)
{
  gkyl_array_release(up->quad);
  gkyl_free(up);
}
extern "C" {
#include <gkyl_gk_fluid_moments_priv.h>
}

__global__ static void
gk_fluid_moments_kernel(
  struct gkyl_gk_fluid_moments up, struct gkyl_range range, const struct gkyl_array *state,
  const struct gkyl_array *phi, struct gkyl_array *out
)
{
  int idx[GKYL_MAX_DIM];
  for (long cell = threadIdx.x + blockIdx.x * blockDim.x; cell < range.volume;
       cell += gridDim.x * blockDim.x) {
    gkyl_sub_range_inv_idx(&range, cell, idx);
    long loc = gkyl_range_idx(&range, idx);
    gk_fluid_moments_cell(
      &up, (const double *)gkyl_array_cfetch(state, loc),
      phi ? (const double *)gkyl_array_cfetch(phi, loc) : 0, up.quad,
      (double *)gkyl_array_fetch(out, loc)
    );
  }
}

void
gkyl_gk_fluid_moments_advance_cu(
  const struct gkyl_gk_fluid_moments *up, const struct gkyl_range *range,
  const struct gkyl_array *state, const struct gkyl_array *phi, struct gkyl_array *out
)
{
  struct gkyl_gk_fluid_moments device = *up;
  device.quad = up->quad->on_dev;
  gk_fluid_moments_kernel<<<range->nblocks, range->nthreads>>>(
    device, *range, state->on_dev, phi ? phi->on_dev : 0, out->on_dev
  );
}
