await replace("gyrokinetic/zero/gk_fluid_moments.c",`#include <assert.h>
#include <math.h>
#include <gkyl_alloc.h>
#include <gkyl_array_ops.h>
#include <gkyl_gk_fluid_moments_priv.h>

// Copy one DG component through scalar scratch, including between vector arrays.
static void
gk_fluid_moments_copy(const struct gkyl_gk_fluid_moments *up, const struct gkyl_range *range,
  struct gkyl_array *out, int oc, double factor, const struct gkyl_array *inp, int ic)
{
  int nb = up->basis.num_basis;
  gkyl_array_set_offset_range(up->tmp, factor, inp, ic*nb, range);
  gkyl_array_set_offset_range(out, 1.0, up->tmp, oc*nb, range);
}

static void
gk_fluid_moments_perp(const struct gkyl_gk_fluid_moments *up, const struct gkyl_range *range,
  const struct gkyl_array *state)
{
  gkyl_dg_mul_op_range(&up->basis, 0, up->pperp, 0, up->bmag, 3, state, range);
}

static void
gk_fluid_moments_perp_zero(const struct gkyl_gk_fluid_moments *up, const struct gkyl_range *range,
  const struct gkyl_array *state)
{
  gkyl_array_clear_range(up->pperp, 0.0, range);
}

static void
gk_fluid_moments_project_perp(const struct gkyl_gk_fluid_moments *up, const struct gkyl_range *range,
  const struct gkyl_array *state, const struct gkyl_array *prim)
{
  gkyl_dg_mul_op_range(&up->basis, 0, up->pperp, 0, state, 3, prim, range);
}

static void
gk_fluid_moments_project_perp_zero(const struct gkyl_gk_fluid_moments *up, const struct gkyl_range *range,
  const struct gkyl_array *state, const struct gkyl_array *prim)
{
  gkyl_array_clear_range(up->pperp, 0.0, range);
}

// Recover u and weighted pressures. No division by J is needed.
static void
gk_fluid_moments_recover(const struct gkyl_gk_fluid_moments *up, const struct gkyl_range *range,
  const struct gkyl_array *state)
{
  gkyl_dg_div_op_range(up->mem, &up->basis, 0, up->upar, 1, state, 0, state, range);
  up->perp(up, range, state);
  gkyl_dg_mul_op_range(&up->basis, 0, up->ppar, 0, up->upar, 1, state, range);
  gkyl_array_scale_range(up->ppar, -1.0, range);
  gkyl_array_set_offset_range(up->tmp, 2.0, state, 2*up->basis.num_basis, range);
  gkyl_array_accumulate_range(up->ppar, 1.0, up->tmp, range);
  gkyl_array_accumulate_range(up->ppar, -2.0, up->pperp, range);
}

static void
gk_fluid_moments_linear(const struct gkyl_gk_fluid_moments *up, const struct gkyl_range *range,
  const struct gkyl_array *state, const struct gkyl_array *phi)
{
  gk_fluid_moments_copy(up, range, up->result, 0, up->factor, state, up->component);
}

static void
gk_fluid_moments_m2perp(const struct gkyl_gk_fluid_moments *up, const struct gkyl_range *range,
  const struct gkyl_array *state, const struct gkyl_array *phi)
{
  up->perp(up, range, state);
  gk_fluid_moments_copy(up, range, up->result, 0, 2.0/up->mass, up->pperp, 0);
}

static void
gk_fluid_moments_m2par(const struct gkyl_gk_fluid_moments *up, const struct gkyl_range *range,
  const struct gkyl_array *state, const struct gkyl_array *phi)
{
  up->perp(up, range, state);
  gkyl_array_set_offset_range(up->ppar, 2.0/up->mass, state, 2*up->basis.num_basis, range);
  gkyl_array_accumulate_range(up->ppar, -2.0/up->mass, up->pperp, range);
  gk_fluid_moments_copy(up, range, up->result, 0, 1.0, up->ppar, 0);
}

static void
gk_fluid_moments_m3par(const struct gkyl_gk_fluid_moments *up, const struct gkyl_range *range,
  const struct gkyl_array *state, const struct gkyl_array *phi)
{
  gk_fluid_moments_recover(up, range, state);
  // M3par = u*(M2par+2*J*ppar/m).
  gkyl_array_scale_range(up->ppar, 2.0/up->mass, range);
  gkyl_array_set_offset_range(up->tmp, 2.0/up->mass, state, 2*up->basis.num_basis, range);
  gkyl_array_accumulate_range(up->ppar, 1.0, up->tmp, range);
  gkyl_array_accumulate_range(up->ppar, -2.0/up->mass, up->pperp, range);
  gkyl_dg_mul_op_range(&up->basis, 0, up->result, 0, up->upar, 0, up->ppar, range);
}

static void
gk_fluid_moments_m3perp(const struct gkyl_gk_fluid_moments *up, const struct gkyl_range *range,
  const struct gkyl_array *state, const struct gkyl_array *phi)
{
  gkyl_dg_div_op_range(up->mem, &up->basis, 0, up->upar, 1, state, 0, state, range);
  up->perp(up, range, state);
  gkyl_array_scale_range(up->pperp, 2.0/up->mass, range);
  gkyl_dg_mul_op_range(&up->basis, 0, up->result, 0, up->upar, 0, up->pperp, range);
}

static void
gk_fluid_moments_maxwellian(const struct gkyl_gk_fluid_moments *up, const struct gkyl_range *range,
  const struct gkyl_array *state, const struct gkyl_array *phi)
{
  gk_fluid_moments_recover(up, range, state);
  gk_fluid_moments_copy(up, range, up->result, 0, 1.0/up->mass, state, 0);
  gk_fluid_moments_copy(up, range, up->result, 1, 1.0, up->upar, 0);
  gkyl_array_accumulate_range(up->ppar, 2.0, up->pperp, range);
  gkyl_array_scale_range(up->ppar, 1.0/(2*up->vdim-1), range);
  gkyl_dg_div_op_range(up->mem, &up->basis, 2, up->result, 0, up->ppar, 0, state, range);
}

static void
gk_fluid_moments_bimaxwellian(const struct gkyl_gk_fluid_moments *up, const struct gkyl_range *range,
  const struct gkyl_array *state, const struct gkyl_array *phi)
{
  gk_fluid_moments_recover(up, range, state);
  gk_fluid_moments_copy(up, range, up->result, 0, 1.0/up->mass, state, 0);
  gk_fluid_moments_copy(up, range, up->result, 1, 1.0, up->upar, 0);
  gkyl_dg_div_op_range(up->mem, &up->basis, 2, up->result, 0, up->ppar, 0, state, range);
  gkyl_dg_div_op_range(up->mem, &up->basis, 3, up->result, 0, up->pperp, 0, state, range);
}

static void
gk_fluid_moments_m0m1m2(const struct gkyl_gk_fluid_moments *up, const struct gkyl_range *range,
  const struct gkyl_array *state, const struct gkyl_array *phi)
{
  for (int c = 0; c < 3; ++c)
    gk_fluid_moments_copy(up, range, up->result, c, (c == 2 ? 2.0 : 1.0)/up->mass, state, c);
}

static void
gk_fluid_moments_m0m1m2parperp(const struct gkyl_gk_fluid_moments *up, const struct gkyl_range *range,
  const struct gkyl_array *state, const struct gkyl_array *phi)
{
  gk_fluid_moments_m0m1m2(up, range, state, phi);
  up->perp(up, range, state);
  gkyl_array_set_offset_range(up->ppar, 2.0/up->mass, state, 2*up->basis.num_basis, range);
  gkyl_array_accumulate_range(up->ppar, -2.0/up->mass, up->pperp, range);
  gk_fluid_moments_copy(up, range, up->result, 2, 1.0, up->ppar, 0);
  gk_fluid_moments_copy(up, range, up->result, 3, 2.0/up->mass, up->pperp, 0);
}

static void
gk_fluid_moments_hamiltonian(const struct gkyl_gk_fluid_moments *up, const struct gkyl_range *range,
  const struct gkyl_array *state, const struct gkyl_array *phi)
{
  assert(phi);
  gk_fluid_moments_copy(up, range, up->result, 0, 1.0/up->mass, state, 0);
  gk_fluid_moments_copy(up, range, up->result, 1, 1.0, state, 1);
  gkyl_dg_mul_op_range(&up->basis, 0, up->ppar, 0, phi, 0, state, range);
  gkyl_array_scale_range(up->ppar, up->charge/up->mass, range);
  gkyl_array_set_offset_range(up->tmp, 1.0, state, 2*up->basis.num_basis, range);
  gkyl_array_accumulate_range(up->ppar, 1.0, up->tmp, range);
  gk_fluid_moments_copy(up, range, up->result, 2, 1.0, up->ppar, 0);
}

static void
gk_fluid_moments_finish(const struct gkyl_gk_fluid_moments *up, const struct gkyl_range *range,
  struct gkyl_array *out)
{
  for (int c = 0; c < up->num_mom; ++c)
    gk_fluid_moments_copy(up, range, out, c, 1.0, up->result, c);
}

static void
gk_fluid_moments_integrate(const struct gkyl_gk_fluid_moments *up, const struct gkyl_range *range,
  struct gkyl_array *out)
{
  struct gkyl_range_iter iter;
  gkyl_range_iter_init(&iter, range);
  while (gkyl_range_iter_next(&iter)) {
    long loc = gkyl_range_idx(range, iter.idx);
    const double *dg = gkyl_array_cfetch(up->result, loc);
    double *integral = gkyl_array_fetch(out, loc);
    for (int c = 0; c < up->num_mom; ++c)
      integral[c] = up->cell_factor*dg[c*up->basis.num_basis];
  }
}

struct gkyl_gk_fluid_moments *
gkyl_gk_fluid_moments_inew(const struct gkyl_gk_fluid_moments_inp *inp)
{
  assert(inp->vdim == 1 || inp->vdim == 2);
  assert(inp->mass > 0 && inp->bmag);
  struct gkyl_gk_fluid_moments *up = gkyl_malloc(sizeof *up);
  *up = (struct gkyl_gk_fluid_moments) {
    .basis = *inp->basis, .vdim = inp->vdim, .mass = inp->mass, .charge = inp->charge,
    .num_mom = 1, .factor = 1.0/inp->mass, .cell_factor = 1.0,
    .perp = inp->vdim == 1 ? gk_fluid_moments_perp_zero : gk_fluid_moments_perp,
    .project_perp = inp->vdim == 1 ? gk_fluid_moments_project_perp_zero : gk_fluid_moments_project_perp,
    .finish = inp->integrated ? gk_fluid_moments_integrate : gk_fluid_moments_finish,
  };
  switch (inp->moment) {
    case GKYL_F_MOMENT_M0:
    case GKYL_F_MOMENT_M1:
    case GKYL_F_MOMENT_M2:
      up->component = inp->moment == GKYL_F_MOMENT_M0 ? 0 : inp->moment == GKYL_F_MOMENT_M1 ? 1 : 2;
      up->factor *= up->component == 2 ? 2.0 : 1.0;
      up->calc = gk_fluid_moments_linear;
      break;
    case GKYL_F_MOMENT_M2PAR: up->calc = gk_fluid_moments_m2par; break;
    case GKYL_F_MOMENT_M2PERP: up->calc = gk_fluid_moments_m2perp; break;
    case GKYL_F_MOMENT_M3PAR: up->calc = gk_fluid_moments_m3par; break;
    case GKYL_F_MOMENT_M3PERP: up->calc = gk_fluid_moments_m3perp; break;
    case GKYL_F_MOMENT_MAXWELLIAN:
      up->num_mom = 3; up->calc = gk_fluid_moments_maxwellian; break;
    case GKYL_F_MOMENT_BIMAXWELLIAN:
      up->num_mom = 4; up->calc = gk_fluid_moments_bimaxwellian; break;
    case GKYL_F_MOMENT_M0M1M2:
      up->num_mom = 3; up->calc = gk_fluid_moments_m0m1m2; break;
    case GKYL_F_MOMENT_M0M1M2PARM2PERP:
      up->num_mom = inp->vdim+2; up->calc = gk_fluid_moments_m0m1m2parperp; break;
    case GKYL_F_MOMENT_HAMILTONIAN:
      up->num_mom = 3; up->calc = gk_fluid_moments_hamiltonian; break;
    default: gkyl_exit("Unsupported gyrokinetic fluid moment.");
  }
  for (int d = 0; d < inp->grid->ndim; ++d)
    up->cell_factor *= inp->grid->dx[d]/sqrt(2.0);
  struct gkyl_array *(*alloc)(enum gkyl_elem_type, size_t, size_t) =
    inp->use_gpu ? gkyl_array_cu_dev_new : gkyl_array_new;
  int nb = inp->basis->num_basis;
  up->bmag = gkyl_array_acquire(inp->bmag);
  up->upar = alloc(GKYL_DOUBLE, nb, inp->range_ext->volume);
  up->ppar = alloc(GKYL_DOUBLE, nb, inp->range_ext->volume);
  up->pperp = alloc(GKYL_DOUBLE, nb, inp->range_ext->volume);
  up->tmp = alloc(GKYL_DOUBLE, nb, inp->range_ext->volume);
  up->result = alloc(GKYL_DOUBLE, 4*nb, inp->range_ext->volume);
  up->mem = inp->use_gpu ? gkyl_dg_bin_op_mem_cu_dev_new(inp->range->volume, nb) :
    gkyl_dg_bin_op_mem_new(inp->range->volume, nb);
