static void
test_spatial_products(void)
{
  struct gkyl_basis basis;
  gkyl_cart_modal_serendip(&basis, 1, 1);
  struct gkyl_rect_grid grid;
  double lower[] = {-1}, upper[] = {1};
  int cells[] = {1}, ghost[] = {1};
  gkyl_rect_grid_init(&grid, 1, lower, upper, cells);
  struct gkyl_range ext, local;
  gkyl_create_grid_ranges(&grid, ghost, &ext, &local);
  struct gkyl_array *state = gkyl_array_new(GKYL_DOUBLE, 8, ext.volume);
  struct gkyl_array *out = gkyl_array_new(GKYL_DOUBLE, 2, ext.volume);
  long loc = gkyl_range_idx(&local, local.lower);
  double *f = gkyl_array_fetch(state, loc);
  // Jn=2+x, u=3+x, Tpar/m=5. M3par=144+156x+60x^2+11x^3+x^4.
  f[0] = 2 * sqrt(2.0);
  f[1] = sqrt(2.0 / 3);
  f[2] = 3 * sqrt(2.0);
  f[3] = sqrt(2.0 / 3);
  f[4] = 5 * sqrt(2.0);
  struct gkyl_gk_fluid_moments *up =
    gkyl_gk_fluid_moments_new(&basis, &grid, 1, 1, -1, GKYL_F_MOMENT_M3PAR, false, false);
  gkyl_gk_fluid_moments_advance(up, &local, state, 0, out);
  const double *result = gkyl_array_cfetch(out, loc);
  TEST_CHECK(gkyl_compare(result[0], 164.2 * sqrt(2.0), 1e-12));
  TEST_CHECK(gkyl_compare(result[1], 162.6 * sqrt(2.0 / 3), 1e-12));
  gkyl_gk_fluid_moments_release(up);
  gkyl_array_release(out);
  gkyl_array_release(state);
}

static void
test_cpu(void)
{
  test_moments(false);
}
#ifdef GKYL_HAVE_CUDA
static void
test_gpu(void)
{
  test_moments(true);
}
#endif
TEST_LIST = {
  {"fluid_moments_cpu", test_cpu},
  {"fluid_moments_spatial_products", test_spatial_products},
#ifdef GKYL_HAVE_CUDA
  {"fluid_moments_gpu", test_gpu},
#endif
  {NULL, NULL}
};

