  //    fin_neut[i] = app->species[i].f;
  //  }
  //  gk_species_scaling_cross_moms(app, gks, gkr, fin, fin_neut);
  app->stat.species_diag_calc_tm += gkyl_time_diff_now_sec(wst);

  struct timespec wtm = gkyl_wall_clock();
  app->stat.species_diag_io_tm += gkyl_time_diff_now_sec(wtm);
}

static void
gk_species_scaling_write_disabled(
  gkyl_gyrokinetic_app *app, struct gk_species *gks, struct gk_scaling *sca, int ridx, double tm,
  int frame
)
{
  // Do nothing
    const double *prim = gkyl_array_cfetch(host, gkyl_range_idx(&app->local, app->local.lower));
    assert(gkyl_compare(prim[0], sqrt(2.0) * upar, 1e-10));
    assert(gkyl_compare(prim[app->basis.num_basis], sqrt(2.0) * 19.0 / 3, 1e-10));
    gkyl_array_release(host);
  }
  gkyl_gyrokinetic_app_release(app);
  gkyl_gyrokinetic_comms_release(comm);
}

int
main(int argc, char **argv)
{
  struct gkyl_app_args args = parse_app_args(argc, argv);
  run_test(args.use_gpu, GKYL_LBO_COLLISIONS, false, false);
  run_test(args.use_gpu, GKYL_LBO_COLLISIONS, true, false);
  run_test(args.use_gpu, GKYL_BGK_COLLISIONS, false, false);
  run_test(args.use_gpu, GKYL_BGK_COLLISIONS, true, false);
  run_test(args.use_gpu, GKYL_BGK_COLLISIONS, true, true);
  puts("Fluid species projection, scaling, collision partners, and restart: passed.");
  return 0;
}
