// Read a packed fluid state, validating its configuration grid and layout first.
enum gkyl_array_rio_status gk_species_fluid_read(
  struct gkyl_gyrokinetic_app *app, struct gk_species *gks, const char *fname
);

/**
 * Compute species initial conditions.
 *
 * @param app gyrokinetic app object.
 * @param species Species object.
 * @param t0 Time for use in ICs.
 */
void gk_species_apply_ic(gkyl_gyrokinetic_app *app, struct gk_species *species, double t0);

/**

item.aggregated_output:
  gks->bc_func = gk_species_apply_bc_static;
  gks->release_func = gk_species_release_static;
  gks->step_f_func = gk_species_step_f_static;
  gks->combine_func = gk_species_combine_static;
  gks->copy_func = gk_species_copy_range_static;
  gks->write_func = gk_species_write_static;
  gks->write_cfl_func = gk_species_write_cfl_disabled;
  gks->write_mom_func = gks->info.scaling.type == GKYL_GK_SPECIES_SCALING_ADIABATIC ?
                          gk_species_write_mom_dynamic :
                          gk_species_write_mom_static;
  gks->calc_integrated_mom_func = gk_species_calc_integrated_mom_static;
  gks->write_integrated_mom_func = gk_species_write_integrated_mom_static;
  gks->calc_L2norm_func = gk_species_calc_L2norm_static;
  gks->write_L2norm_func = gk_species_write_L2norm_static;
  gks->calc_int_mom_dt_func = gk_species_calc_int_mom_dt_disabled;
}

void
gk_species_apply_ic(gkyl_gyrokinetic_app *app, struct gk_species *gks, double t0)
{
  if (gks->info.init_from_file.type == 0) {
    gk_species_projection_calc(app, gks, &gks->proj_init, gks->f, t0);
  } else if (gks->is_fluid) {
    enum gkyl_array_rio_status status =
      gk_species_fluid_read(app, gks, gks->info.init_from_file.file_name);
    if (status != GKYL_ARRAY_RIO_SUCCESS) {
      gkyl_exit("Unable to import fluid configuration-space state.");
    }
  }

  // We are pre-computing source for now as it is time-independent.
  gk_species_source_calc(app, gks, &gks->src, gks->lte.f_lte, t0);
}

void
gk_species_apply_ic_cross(gkyl_gyrokinetic_app *app, struct gk_species *gks_self, double t0)
{
  // IC setup step that depends on the IC of other species.
  if (app->field->init_phi_pol && gks_self->info.scale_with_polarization) {
    // Scale the distribution function so its guiding center density is computed
    // given the polarization density and the guiding center density of other species.

    // Compute the polarization density.
    struct gkyl_array *npol = mkarr(app->use_gpu, app->basis.num_basis, app->local_ext.volume);

    struct gkyl_gyrokinetic_pol_density *npol_op =
      gkyl_gyrokinetic_pol_density_new(app->basis, app->grid, app->use_gpu);
    gkyl_gyrokinetic_pol_density_advance(
      npol_op, &app->local, app->field->epsilon, app->field->phi_pol, npol
    );
    gkyl_gyrokinetic_pol_density_release(npol_op);

    // Calculate the guiding center density of this species: (npol - q_other*n^G_other)/q_self.
    for (int i = 0; i < app->num_species; ++i) {
      struct gk_species *gks = &app->species[i];
      gk_species_moment_calc(&gks->m0, gks->local, app->local, gks->f);
      if (strcmp(gks->info.name, gks_self->info.name)) {
        gkyl_array_accumulate(npol, -gks->info.charge, gks->m0.marr);
      }
    }
    gkyl_array_scale(npol, 1. / gks_self->info.charge);

    // Scale the distribution function so it has this guiding center density.
    struct gkyl_dg_bin_op_mem *div_mem =
      app->use_gpu ? gkyl_dg_bin_op_mem_cu_dev_new(app->local.volume, app->basis.num_basis) :
                     gkyl_dg_bin_op_mem_new(app->local.volume, app->basis.num_basis);
    struct gkyl_array *den_mod = mkarr(app->use_gpu, app->basis.num_basis, app->local_ext.volume);

    gkyl_dg_div_op_range(
      div_mem, &app->basis, 0, den_mod, 0, npol, 0, gks_self->m0.marr, &app->local
    );
    gkyl_dg_mul_conf_phase_op_range(
      &app->basis, &gks_self->basis, gks_self->f, den_mod, gks_self->f, &app->local_ext,
      &gks_self->local_ext
    );

    gkyl_array_release(den_mod);
    gkyl_dg_bin_op_mem_release(div_mem);
    gkyl_array_release(npol);
  }

  // Store initial density in scaling operator.
  gk_species_scaling_apply_ic_cross(app, gks_self, &gks_self->sca);
}
    gks->write_cfl_func = gk_species_write_cfl_enabled;
  } else {
    gks->write_cfl_func = gk_species_write_cfl_disabled;
  }
  gks->write_mom_func = gk_species_write_mom_dynamic;
  gks->calc_integrated_mom_func = gk_species_calc_integrated_mom_dynamic;
  gks->write_integrated_mom_func = gk_species_write_integrated_mom_dynamic;
  gks->calc_L2norm_func = gk_species_calc_L2norm_dynamic;
  gks->write_L2norm_func = gk_species_write_L2norm_dynamic;
  if (gks->info.time_rate_diagnostics) {
    gks->calc_int_mom_dt_func = gk_species_calc_int_mom_dt_enabled;
  } else {
    gks->calc_int_mom_dt_func = gk_species_calc_int_mom_dt_disabled;
  }
}

void
gk_species_file_import_init(
  struct gkyl_gyrokinetic_app *app, struct gk_species *gks, struct gkyl_gyrokinetic_ic_import inp
)
{
  // Import initial condition from a file. Intended options include importing:
  //   1) ICs with same grid.
  //   2) ICs one dimensionality lower (e.g. 2x2v for 3x2v sim).
  //   3) ICs with same grid extents but different resolution (NYI).

  struct gkyl_rect_grid grid = gks->grid;
  int pdim = grid.ndim;
  int cdim = app->cdim;
  int vdim = pdim - cdim;
  int poly_order = app->poly_order;

  struct gkyl_rect_grid grid_do; // Donor grid.
  struct gkyl_array_header_info hdr;
  int pdim_do, vdim_do, cdim_do;
  bool same_res = true;

  // Read the header of the input file, extract needed info an create a grid
  // and other things needed.
  FILE *fp;
  with_file(fp, inp.file_name, "r")
  {
    int status = gkyl_grid_sub_array_header_read_fp(&grid_do, &hdr, fp);

    pdim_do = grid_do.ndim;
    vdim_do = vdim; // Assume velocity space dimensionality is the same.
    cdim_do = pdim_do - vdim_do;

    // Perform some basic checks.
    if (pdim_do == pdim) {
      // Check if the grid resolution is the same.
      for (int d = 0; d < pdim; d++) {
        same_res = same_res && (grid_do.cells[d] == grid.cells[d]);
      }
    } else {
      // Assume the loaded file has one lower conf-space dimension.
      // Primarily meant for loading:
      //   - 1x2v for a 2x2v sim.
      //   - 2x2v for a 3x2v sim.
      assert(pdim_do == pdim - 1);
      double tol_eq = 1e-10;
      for (int d = 0; d < cdim_do - 1; d++) {
        assert(gkyl_compare_double(grid_do.lower[d], grid.lower[d], tol_eq));
        assert(gkyl_compare_double(grid_do.upper[d], grid.upper[d], tol_eq));
        assert(gkyl_compare_double(grid_do.dx[d], grid.dx[d], tol_eq));
        assert(grid_do.cells[d] == grid.cells[d]);
      }
      assert(gkyl_compare_double(grid_do.lower[cdim_do - 1], grid.lower[cdim - 1], tol_eq));
      assert(gkyl_compare_double(grid_do.upper[cdim_do - 1], grid.upper[cdim - 1], tol_eq));
      assert(gkyl_compare_double(grid_do.dx[cdim_do - 1], grid.dx[cdim - 1], tol_eq));
      assert(grid_do.cells[cdim_do - 1] == grid.cells[cdim - 1]);
      for (int d = 0; d < vdim; d++) {
        assert(gkyl_compare_double(grid_do.lower[cdim_do + d], grid.lower[cdim + d], tol_eq));
        assert(gkyl_compare_double(grid_do.upper[cdim_do + d], grid.upper[cdim + d], tol_eq));
        assert(gkyl_compare_double(grid_do.dx[cdim_do + d], grid.dx[cdim + d], tol_eq));
        assert(grid_do.cells[cdim_do + d] == grid.cells[cdim + d]);
      }
    }

    // Read basis info from header, check its consistency.
    struct gkyl_msgpack_map_elem elem_list[] = {
      {.key = "poly_order", .elem_type = GKYL_MP_UNSIGNED_INT, .uval = 0},
      {.key = "basis_type", .elem_type = GKYL_MP_STRING, .cval = 0}
    };
    int elem_list_len = sizeof(elem_list) / sizeof(elem_list[0]);
    gkyl_msgpack_to_map_elem_list(
      &(struct gkyl_msgpack_data){.meta = hdr.meta, .meta_sz = hdr.meta_size}, elem_list_len,
      elem_list
    );
    assert(
      strcmp(
        gks->basis.id, gkyl_msgpack_map_elem_get_string(elem_list_len, elem_list, "basis_type")
      ) == 0
    );
    assert(poly_order == gkyl_msgpack_map_elem_get_uint(elem_list_len, elem_list, "poly_order"));
    gkyl_msgpack_map_elem_release_string(elem_list_len, elem_list, "basis_type");

    gkyl_grid_sub_array_header_release(&hdr);
  }

  // Donor basis.
  struct gkyl_basis basis_do;
  switch (gks->basis.b_type) {
    case GKYL_BASIS_MODAL_GKHYBRID:
    case GKYL_BASIS_MODAL_SERENDIPITY:
      if (poly_order > 1) {
        gkyl_cart_modal_serendip(&basis_do, pdim_do, poly_order);
      } else if (poly_order == 1) {
        // p=2 in vparallel
        gkyl_cart_modal_gkhybrid(&basis_do, cdim_do, vdim_do);
      }
      break;
    default:
      assert(false);
      break;
  }

  // Donor global range.
  int ghost_do[pdim_do];
  for (int d = 0; d < cdim_do; d++) {
    ghost_do[d] = 1;
  }
  for (int d = 0; d < vdim_do; d++) {
    ghost_do[cdim_do + d] = 0;
  }
  struct gkyl_range global_ext_do, global_do;
  gkyl_create_grid_ranges(&grid_do, ghost_do, &global_ext_do, &global_do);

  // Create a donor communicator.
  int cuts_tar[GKYL_MAX_DIM] = {-1}, cuts_do[GKYL_MAX_CDIM] = {-1};
  gkyl_rect_decomp_get_cuts(app->decomp, cuts_tar);
  if (cdim_do == cdim - 1) {
    for (int d = 0; d < cdim_do - 1; d++) {
      cuts_do[d] = cuts_tar[d];
    }
    cuts_do[cdim_do - 1] = cuts_tar[cdim - 1];
  } else {
    for (int d = 0; d < cdim; d++) {
      cuts_do[d] = cuts_tar[d];
    }
  }
  // Set velocity space cuts to 1 as we do not use MPI in vel-space.
  for (int d = 0; d < vdim; d++) {
    cuts_do[cdim_do + d] = 1;
  }

  struct gkyl_rect_decomp *decomp_do = gkyl_rect_decomp_new_from_cuts(pdim_do, cuts_do, &global_do);
  struct gkyl_comm *comm_do = gkyl_comm_split_comm(gks->comm, 0, decomp_do);

  // Donor local range.
  int my_rank = 0;
  gkyl_comm_get_rank(comm_do, &my_rank);

  struct gkyl_range local_ext_do, local_do;
  gkyl_create_ranges(&decomp_do->ranges[my_rank], ghost_do, &local_ext_do, &local_do);

  // Donor array.
  struct gkyl_array *fdo = mkarr(app->use_gpu, basis_do.num_basis, local_ext_do.volume);
  struct gkyl_array *fdo_host =
    app->use_gpu ? mkarr(false, basis_do.num_basis, local_ext_do.volume) : gkyl_array_acquire(fdo);

  // Read donor distribution function and Jacobian inverse.
  struct gkyl_app_restart_status rstat;
  rstat.io_status = gkyl_comm_array_read(comm_do, &grid_do, &local_do, fdo_host, inp.file_name);

  bool scale_by_jacobtot = false;
  with_file(fp, inp.jacobtot_inv_file_name, "r")
  {
    // Configuration space donor grid and basis
    struct gkyl_rect_grid conf_grid_do;
    gkyl_rect_grid_init(&conf_grid_do, cdim_do, grid_do.lower, grid_do.upper, grid_do.cells);
    struct gkyl_basis conf_basis_do;
    gkyl_cart_modal_serendip(&conf_basis_do, cdim_do, poly_order);
    // Configuration space donor ranges and decomposition.
    struct gkyl_range conf_local_ext_do, conf_local_do, conf_global_ext_do, conf_global_do;
    gkyl_create_grid_ranges(&conf_grid_do, ghost_do, &conf_global_ext_do, &conf_global_do);
    struct gkyl_rect_decomp *conf_decomp_do =
      gkyl_rect_decomp_new_from_cuts(cdim_do, cuts_do, &conf_global_do);
    gkyl_create_ranges(
      &conf_decomp_do->ranges[my_rank], ghost_do, &conf_local_ext_do, &conf_local_do
    );
    // Read and multiply by the reciprocal of jacobtot.
    struct gkyl_array *jacobtot_inv_do_host =
      mkarr(false, conf_basis_do.num_basis, conf_local_ext_do.volume);
    rstat.io_status = gkyl_comm_array_read(
      comm_do, &conf_grid_do, &conf_local_do, jacobtot_inv_do_host, inp.jacobtot_inv_file_name
    );
    gkyl_dg_mul_conf_phase_op_range(
      &conf_basis_do, &basis_do, fdo_host, jacobtot_inv_do_host, fdo_host, &conf_local_ext_do,
      &local_ext_do
    );
    gkyl_array_release(jacobtot_inv_do_host);
    gkyl_rect_decomp_release(conf_decomp_do);
    scale_by_jacobtot = true;
  }

  bool scale_by_jacobvel = false;
  with_file(fp, inp.jacobvel_file_name, "r")
  {
    // Read and multiply by the reciprocal of jacobvel.
    struct gkyl_array *jacobvel_do_host = mkarr(false, 1, local_ext_do.volume);
    rstat.io_status =
      gkyl_comm_array_read(comm_do, &grid_do, &local_do, jacobvel_do_host, inp.jacobvel_file_name);
    gkyl_array_divide_by_cell(fdo_host, jacobvel_do_host);
    gkyl_array_release(jacobvel_do_host);
    scale_by_jacobvel = true;
  }

  if (app->use_gpu) {
    gkyl_array_copy(fdo, fdo_host);
  }

  if (pdim_do == pdim - 1) {
    struct gkyl_translate_dim *transdim =
      gkyl_translate_dim_new(cdim_do, basis_do, cdim, gks->basis, -1, GKYL_NO_EDGE, app->use_gpu);
    gkyl_translate_dim_advance(transdim, &local_do, &gks->local, fdo, 1, gks->f);
    gkyl_translate_dim_release(transdim);
  } else {
    if (same_res) {
      gkyl_array_copy(gks->f, fdo);
    } else {
      // Interpolate the donor distribution to the target grid.
      struct gkyl_dg_interpolate *interp = gkyl_dg_interpolate_new(
        app->cdim, &gks->basis, &grid_do, &grid, &local_do, &gks->local, ghost_do, app->use_gpu
      );
      gkyl_dg_interpolate_advance(interp, fdo, gks->f);
      gkyl_dg_interpolate_release(interp);
    }
  }

  if (inp.type == GKYL_IC_IMPORT_AF) {
    // Scale f by a conf-space factor.
    gkyl_proj_on_basis *proj_conf_scale = gkyl_proj_on_basis_new(
      &app->grid, &app->basis, poly_order + 1, 1, inp.conf_scale, inp.conf_scale_ctx
    );
    struct gkyl_array *xfac = mkarr(app->use_gpu, app->basis.num_basis, app->local_ext.volume);
    struct gkyl_array *xfac_ho = app->use_gpu ?
                                   mkarr(false, app->basis.num_basis, app->local_ext.volume) :
                                   gkyl_array_acquire(xfac);
    gkyl_proj_on_basis_advance(proj_conf_scale, 0.0, &app->local, xfac_ho);
    gkyl_array_copy(xfac, xfac_ho);
    gkyl_dg_mul_conf_phase_op_range(
      &app->basis, &gks->basis, gks->f, xfac, gks->f, &app->local, &gks->local
    );
    gkyl_proj_on_basis_release(proj_conf_scale);
    gkyl_array_release(xfac_ho);
    gkyl_array_release(xfac);
  }

  // Multiply f by the Jacobian.
  if (scale_by_jacobtot) {
    gkyl_dg_mul_conf_phase_op_range(
      &app->basis, &gks->basis, gks->f, app->gk_geom->geo_int.jacobtot, gks->f, &app->local,
      &gks->local
    );
  }

  // Multiply f by the velocity space Jacobian.
  if (scale_by_jacobvel) {
    gkyl_array_scale_by_cell(gks->f, gks->vel_map->jacobvel);
  }

  if (inp.enforce_positivity) {
    // Positivity enforcing by shifting f (ps=positivity shift).
    struct gkyl_positivity_shift_gyrokinetic *pos_shift_op = gkyl_positivity_shift_gyrokinetic_new(
      app->basis, gks->basis, gks->grid, gks->info.mass, app->gk_geom, gks->vel_map,
      &app->local_ext, app->use_gpu
    );

    gkyl_positivity_shift_gyrokinetic_advance(
      pos_shift_op, &app->local, &gks->local, gks->f, gks->m0.marr, gks->m0.marr
    );
    gyrokinetic_app_geometry_read_and_copy_surf(
      app, app->gk_geom->geo_surf[dir].deltats, arr_surf_ho1, arr_surf_ho2,
      geometry_inp->geometry_path, "deltats", dir
    );
    // jacobgeo_ratio is not used in single block.
    gkyl_array_clear(app->gk_geom->geo_surf[dir].jacobgeo_ratio, 0.0);
    gkyl_array_shiftc(app->gk_geom->geo_surf[dir].jacobgeo_ratio, pow(sqrt(2.0), app->cdim), 0);
  }

  gkyl_array_release(arr_ho1);
  gkyl_array_release(arr_ho3);
  gkyl_array_release(arr_ho6);
  gkyl_array_release(arr_ho9);
  gkyl_array_release(arr_surf_ho1);
  gkyl_array_release(arr_surf_ho2);
  gkyl_array_release(arr_surf_ho3);
  gkyl_array_release(arr_surf_ho6);
  gkyl_array_release(arr_surf_ho9);
  gkyl_array_release(arr_surf_ho18);
}

struct gkyl_app_restart_status
gkyl_gyrokinetic_app_from_file_field(gkyl_gyrokinetic_app *app, const char *fname)
{
  struct gkyl_app_restart_status rstat = header_from_file(app, fname);

  if (rstat.io_status == GKYL_ARRAY_RIO_SUCCESS) {
    rstat.io_status =
      gkyl_comm_array_read(app->comm, &app->grid, &app->local, app->field->phi_host, fname);
    if (app->use_gpu) {
      gkyl_array_copy(app->field->phi_smooth, app->field->phi_host);
    }
  }

  return rstat;
}

struct gkyl_app_restart_status
gkyl_gyrokinetic_app_from_file_species(gkyl_gyrokinetic_app *app, int sidx, const char *fname)
{
  struct gkyl_app_restart_status rstat = header_from_file(app, fname);

  struct gk_species *gk_s = &app->species[sidx];

  if (rstat.io_status == GKYL_ARRAY_RIO_SUCCESS) {
    if (gk_s->is_fluid) {
      rstat.io_status = gk_species_fluid_read(app, gk_s, fname);
      return rstat;
    }
    rstat.io_status =
      gkyl_comm_array_read(gk_s->comm, &gk_s->grid, &gk_s->local, gk_s->f_host, fname);
    if (app->use_gpu) {
      gkyl_array_copy(gk_s->f, gk_s->f_host);
    }

    if (rstat.io_status == GKYL_ARRAY_RIO_SUCCESS) {
      gk_species_source_calc(app, gk_s, &gk_s->src, gk_s->lte.f_lte, 0.0);
      // Read volume and time integrated boundary flux diagnostics.
      gk_species_bflux_read_voltime_integrated_mom(app, gk_s, &gk_s->bflux);
    }
  }

  return rstat;
}

struct gkyl_app_restart_status
gkyl_gyrokinetic_app_from_file_neut_species(gkyl_gyrokinetic_app *app, int sidx, const char *fname)
{
  struct gkyl_app_restart_status rstat = header_from_file(app, fname);

  struct gk_neut_species *gkns = &app->neut_species[sidx];

  if (rstat.io_status == GKYL_ARRAY_RIO_SUCCESS) {
    rstat.io_status =
      gkyl_comm_array_read(gkns->comm, &gkns->grid, &gkns->local, gkns->f_host, fname);
    if (app->use_gpu) {
      gkyl_array_copy(gkns->f, gkns->f_host);
    }

    if (rstat.io_status == GKYL_ARRAY_RIO_SUCCESS) {
#include <gkyl_gk_species_priv.h>

enum gkyl_array_rio_status
gk_species_fluid_read(gkyl_gyrokinetic_app *app, struct gk_species *gks, const char *fname)
{
  struct gkyl_rect_grid grid;
  struct gkyl_array_header_info hdr = {0};
  enum gkyl_array_rio_status status = gkyl_grid_sub_array_header_read(&grid, &hdr, fname);
  if (status != GKYL_ARRAY_RIO_SUCCESS) {
    return status;
  }
  bool matches = grid.ndim == gks->grid.ndim && hdr.etype == GKYL_DOUBLE &&
                 hdr.esznc == gks->f->esznc;
  for (int d = 0; matches && d < grid.ndim; ++d) {
    matches = grid.cells[d] == gks->grid.cells[d] &&
              gkyl_compare(grid.lower[d], gks->grid.lower[d], 1e-12) &&
              gkyl_compare(grid.upper[d], gks->grid.upper[d], 1e-12);
  }
  struct gkyl_msgpack_map_elem layout[] = {
    {.key = "state_layout", .elem_type = GKYL_MP_STRING, .cval = 0},
    {.key = "vdim", .elem_type = GKYL_MP_UNSIGNED_INT, .uval = 0},
    {.key = "poly_order", .elem_type = GKYL_MP_UNSIGNED_INT, .uval = 0}
  };
  gkyl_msgpack_to_map_elem_list(
    &(struct gkyl_msgpack_data){.meta = hdr.meta, .meta_sz = hdr.meta_size}, 3, layout
  );
  const char *name = gkyl_msgpack_map_elem_get_string(3, layout, "state_layout");
  matches = matches && name && strcmp(name, "Jrho,JMpar,JE,Jpperp/B") == 0 &&
            gkyl_msgpack_map_elem_get_uint(3, layout, "vdim") == gks->info.vdim &&
            gkyl_msgpack_map_elem_get_uint(3, layout, "poly_order") == gks->basis.poly_order;
  gkyl_msgpack_map_elem_release_string(3, layout, "state_layout");
  gkyl_array_header_info_release(&hdr);
  if (!matches) {
    return GKYL_ARRAY_RIO_DATA_MISMATCH;
  }
  status = gkyl_comm_array_read(gks->comm, &gks->grid, &gks->local, gks->f_host, fname);
  if (status == GKYL_ARRAY_RIO_SUCCESS && app->use_gpu) {
    gkyl_array_copy(gks->f, gks->f_host);
  }
  return status;
}

static void
gk_species_fluid_release(const gkyl_gyrokinetic_app *app, const struct gk_species *gks)
{
  if (gks->info.collisionless.type || gks->info.flr.type || gks->info.source.source_id ||
      gks->info.source_bgk.source_bgk_id || gks->info.radiation.radiation_id ||
      gks->info.react.num_react || gks->info.react_neut.num_react || gks->info.positivity.type ||
      gks->info.positivity.quasineutrality_rescale || gks->info.damping.type ||
      gks->info.anomalous_diffusion.anomalous_diff_id ||
      gks->info.time_rate_multiplier.num_multipliers || gks->info.scale_with_polarization ||
      gks->info.time_rate_diagnostics || gks->info.write_omega_cfl || gks->info.mapc2p.mapping ||
      gks->info.boundary_flux_diagnostics.num_diag_moments ||
      gks->info.boundary_flux_diagnostics.num_integrated_diag_moments) {
    gkyl_exit("Fluid gyrokinetic species: requested kinetic-only operator or diagnostic.");
  }
  if (gks->info.collisions.collision_id && !gks->info.collisions.not_in_dfdt) {
    gkyl_exit("Fluid gyrokinetic collisions require not_in_dfdt=true.");
  }
  if (gks->info.scaling.type == GKYL_GK_SPECIES_SCALING_RECYCLING_IZ_BALANCE) {
    gkyl_exit("Recycling/ionization balance is not supported for charged fluid species.");
  }
  if (gks->info.init_from_file.type != GKYL_IC_IMPORT_NONE &&
      (gks->info.init_from_file.type != GKYL_IC_IMPORT_F ||
       gks->info.init_from_file.enforce_positivity || gks->info.init_from_file.conf_scale ||
       gks->info.init_from_file.jacobtot_inv_file_name[0] ||
       gks->info.init_from_file.jacobvel_file_name[0])) {
    gkyl_exit("Fluid initial-state import supports unmodified configuration-space moments only.");
  }
  for (int d = 0; d < GKYL_MAX_VDIM; ++d) {
    if (gks->info.cells[d] || gks->info.lower[d] || gks->info.upper[d]) {
      gkyl_exit("Fluid gyrokinetic species must omit the velocity grid entirely.");
    }
  }
  gks->info.vdim = gks->info.vdim ? gks->info.vdim : 2;
  if (gks->info.collisions.collision_id && app->cdim > 1 && gks->info.vdim == 1) {
    gkyl_exit("Gyrokinetic collision kernels with one velocity dimension require cdim=1.");
  }
  for (int b = 0; b < 2 * app->cdim; ++b) {
    if (gks->info.bcs[b].type != GKYL_BC_GK_SKIP &&
        gks->info.bcs[b].type != GKYL_BC_GK_SPECIES_PERIODIC) {
      gkyl_exit("Kinetic boundary conditions are not supported for fluid gyrokinetic species.");
    }
  }
  if ((gks->info.vdim != 1 && gks->info.vdim != 2) || gks->info.mass <= 0.0 ||
      gks->info.charge == 0.0) {
    gkyl_exit("Invalid fluid gyrokinetic species mass, charge, or vdim.");
  }
  gks->info.is_static = true;
  gks->release_species_func = gk_species_fluid_release;
  gks->grid = app->grid;
 * @param app Gyrokinetic app object.
 * @param src Species source_bgk object to release.
 */
void gk_species_source_bgk_release(
  const struct gkyl_gyrokinetic_app *app, const struct gk_source_bgk *src
);

