  cstr fileNm = cstr_from_fmt("%s-%s_%d.gkyl", app->name, gkns->info.name, frame);
  struct gkyl_app_restart_status rstat =
    gkyl_gyrokinetic_app_from_file_neut_species(app, sidx, fileNm.str);
  gkns->is_first_integ_write_call = false; // append to existing diagnostic
  cstr_drop(&fileNm);

  // Append to existing integrated diagnostics.
  gkns->is_first_integ_write_call = false;
  if (gkns->src.source_id) {
    gkns->src.is_first_integ_write_call = false;
  }
  if (gkns->positivity.type) {
    gkns->positivity.is_first_integ_write_call = false;
  }
  if (gkns->lte.correct_all_moms) {
    gkns->lte.is_first_corr_status_write_call = false;
  }

  return rstat;
}

struct gkyl_app_restart_status
gkyl_gyrokinetic_app_read_from_frame(gkyl_gyrokinetic_app *app, int frame)
{
  struct gkyl_app_restart_status rstat = {.io_status = GKYL_ARRAY_RIO_SUCCESS};
  for (int i = 0; i < app->num_neut_species; i++) {
    if (app->neut_species[i].info.is_static) {
      gk_neut_species_apply_ic(app, &app->neut_species[i], 0.0);
    } else {
      rstat = gkyl_gyrokinetic_app_from_frame_neut_species(app, i, frame);
    }
  }
  for (int i = 0; i < app->num_species; i++) {
    if (app->species[i].info.is_static) {
      gk_species_apply_ic(app, &app->species[i], 0.0);
    } else {
      rstat = gkyl_gyrokinetic_app_from_frame_species(app, i, frame);
    }
  }

  // Set up the response of an adiabatic species (static) from its t=0 moments.
  app->field->init_adiab_func(app, app->field);

  // Restore fluid snapshots only after capturing the equilibrium response.
  // The on-disk state is the same configuration-space moment array as gks->f.
  for (int i = 0; i < app->num_species; ++i) {
    if (app->species[i].is_fluid) {
      rstat = gkyl_gyrokinetic_app_from_frame_species(app, i, frame);
      if (rstat.io_status != GKYL_ARRAY_RIO_SUCCESS) {
        return rstat;
      }
    }
  }

  // Apply ICs that depend on other species.
  for (int i = 0; i < app->num_neut_species; ++i) {
    gkyl_gyrokinetic_app_apply_ic_cross_neut_species(app, i, 0.0);
  }

  if (rstat.io_status == GKYL_ARRAY_RIO_SUCCESS) {
    // Compute the fields and apply BCs.
    struct gkyl_array *distf[app->num_species];
    struct gkyl_array **bflux[app->num_species];
    struct gkyl_array *distf_neut[app->num_neut_species];
    for (int i = 0; i < app->num_species; ++i) {
      distf[i] = app->species[i].f;
      bflux[i] = app->species[i].bflux.f;
    }
    for (int i = 0; i < app->num_neut_species; ++i) {
      distf_neut[i] = app->neut_species[i].f;
    }
    if (app->field->update_field) {
      if (app->field->gkfield_id == GKYL_GK_FIELD_BOLTZMANN) {
        for (int i = 0; i < app->num_species; ++i) {
          struct gk_species *gks = &app->species[i];

    case mpack_type_map: {
      uint32_t count = mpack_tag_map_count(&tag);
      mpack_start_map(w, count);
      for (uint32_t i = 0; i < count; i++) {
        msgpack_copy_value(r, w); // Copy key.
        msgpack_copy_value(r, w); // Copy value.
