  if (rstat.io_status == GKYL_ARRAY_RIO_SUCCESS) {
    if (gk_s->is_fluid) {
      rstat.io_status = gk_species_fluid_read(app, gk_s, fname);
      return rstat;
    }
    rstat.io_status =
      gkyl_comm_array_read(gk_s->comm, &gk_s->grid, &gk_s->local, gk_s->f_host, fname);
    if (app->use_gpu) {
