    if (rstat.io_status == GKYL_ARRAY_RIO_SUCCESS) {
      gk_species_source_calc(app, gk_s, &gk_s->src, gk_s->lte.f_lte, 0.0);
      // Read volume and time integrated boundary flux diagnostics.
