  struct gkyl_msgpack_map_elem old_layout[] = {
    {.key = "state_layout", .elem_type = GKYL_MP_STRING, .cval = "Jn,upar,Tpar/m,Tperp/m"},
    {.key = "vdim", .elem_type = GKYL_MP_UNSIGNED_INT, .uval = 2},
    {.key = "poly_order", .elem_type = GKYL_MP_UNSIGNED_INT, .uval = 1}
