  gkyl_gyrokinetic_app_apply_ic_species(app, 1, 0);
  check_state(app, 1.25 * response); // apply_ic must not reread the file.
  gkyl_gyrokinetic_app_apply_ic(app, 0); // Initialize the field before releasing the app.
  gkyl_gyrokinetic_app_release(app);
  inp.species[1].init_from_file.type = GKYL_IC_IMPORT_NONE;
