+  const double *dens = gkyl_array_cfetch(ion->m0.marr_host,
+    gkyl_range_idx(&donor->local, donor->local.lower));
+  double density = dens[0]/sqrt(2.0); // Weighted density is constant in configuration space.
+  struct gkyl_array *jac = mkarr(false, donor->basis.num_basis, donor->local_ext.volume);
+  gkyl_array_copy(jac, donor->gk_geom->geo_int.jacobtot_inv);
+  gkyl_comm_array_write(donor->comm, &donor->grid, &donor->local, 0, jac,
+    "gk_fluid_species-jacobtot-inv.gkyl");
+  gkyl_array_release(jac);
+  jac = mkarr(false, ion->vel_map->jacobvel->ncomp, ion->vel_map->jacobvel->size);
+  gkyl_array_copy(jac, ion->vel_map->jacobvel);
+  gkyl_comm_array_write(ion->comm, &ion->grid, &ion->local, 0, jac,
+    "gk_fluid_species-jacobvel.gkyl");
+  gkyl_array_release(jac);
+  double factor = 1.4;
+  for (int variant = 0; variant < 6; ++variant) {
+    struct gkyl_gk target = inp;
+    target.species[0].init_from_file = (struct gkyl_gyrokinetic_ic_import) {
+      .type = GKYL_IC_IMPORT_F, .file_name = "gk_fluid_species-ion_0.gkyl",
+    };
+    if (variant == 1) {
+      target.species[0].init_from_file.type = GKYL_IC_IMPORT_AF;
+      target.species[0].init_from_file.conf_scale = constant;
+      target.species[0].init_from_file.conf_scale_ctx = &factor;
+    }
+    if (variant == 2) target.species[0].init_from_file.enforce_positivity = true;
+    if (variant == 3) {
+      snprintf(target.species[0].init_from_file.jacobtot_inv_file_name, 128,
+        "gk_fluid_species-jacobtot-inv.gkyl");
+      snprintf(target.species[0].init_from_file.jacobvel_file_name, 128,
+        "gk_fluid_species-jacobvel.gkyl");
+    }
+    if (variant == 4) target.cells[0] *= 2; // Exercise configuration-space interpolation.
+    if (variant == 5) {
+      // Expand 1x2v into 2x2v, retaining the parallel grid and its decomposition.
+      target.cdim = 2;
+      target.lower[1] = target.lower[0]; target.upper[1] = target.upper[0];
+      target.cells[1] = target.cells[0]; target.cells[0] = 2;
+      target.parallelism.cuts[1] = target.parallelism.cuts[0]; target.parallelism.cuts[0] = 1;
+      target.num_periodic_dir = 2; target.periodic_dirs[1] = 1;
+    }
+    gkyl_gyrokinetic_app *app = gkyl_gyrokinetic_app_new(&target);
+    struct gk_species *species = &app->species[0];
+    double expected = density*(variant == 1 ? factor : 1);
+    // Constructor import is complete before apply_ic, which must not reload it.
+    for (int repeat = 0; repeat < 2; ++repeat) {
+      gk_species_moment_calc(&species->m0, species->local, app->local, species->f);
+      gkyl_array_copy(species->m0.marr_host, species->m0.marr);
+      struct gkyl_range_iter iter;
+      gkyl_range_iter_init(&iter, &app->local);
+      while (gkyl_range_iter_next(&iter)) {
+        const double *m0 = gkyl_array_cfetch(species->m0.marr_host,
+          gkyl_range_idx(&app->local, iter.idx));
+        assert(gkyl_compare(m0[0], pow(sqrt(2.0), app->cdim)*expected, 1e-10));
+        for (int k = 1; k < app->basis.num_basis; ++k) assert(fabs(m0[k]) < 1e-10);
+      }
+      gkyl_array_scale(species->f, factor);
+      expected *= factor;
+      gkyl_gyrokinetic_app_apply_ic_species(app, 0, 0);
+    }
+    gkyl_gyrokinetic_app_apply_ic(app, 0);
+    gkyl_gyrokinetic_app_release(app);
+  }
+}
