// Focused app-level checks of the fluid charged-species representation.
#include <gkyl_gk_species_priv.h>
#include <gkyl_gyrokinetic_comms.h>
#include <rt_arg_parse.h>

static void
constant(double t, const double *xn, double *out, void *ctx)
{
  out[0] = *(double *)ctx;
}

static void
magnetic_field(double t, const double *xn, double *out, void *ctx)
{
  out[0] = out[1] = 0;
  out[2] = *(double *)ctx;
}

static void
mapc2p(double t, const double *xn, double *out, void *ctx)
{
  out[0] = xn[0];
  out[1] = xn[1];
  out[2] = 2 * xn[2];
}

static void
check_arrays(
  const struct gkyl_array *actual, const struct gkyl_array *expected, const struct gkyl_range *range
)
{
  assert(actual->ncomp == expected->ncomp);
  struct gkyl_range_iter iter;
  gkyl_range_iter_init(&iter, range);
  while (gkyl_range_iter_next(&iter)) {
    long loc = gkyl_range_idx(range, iter.idx);
    const double *got = gkyl_array_cfetch(actual, loc), *want = gkyl_array_cfetch(expected, loc);
    for (int c = 0; c < actual->ncomp; ++c) {
      assert(gkyl_compare(got[c], want[c], 1e-11));
    }
  }
}

static void
check_species_reads(gkyl_gyrokinetic_app *app)
{
  int rank;
  gkyl_comm_get_rank(app->comm, &rank);
  if (rank == 0) {
    // Valid magic, version, and file type; truncated before the metadata length.
    FILE *fp = fopen("gk_fluid_species-truncated.gkyl", "wb");
    assert(fp);
    uint64_t version = 1, file_type = 1;
    assert(fwrite("gkyl0", 5, 1, fp) == 1);
    assert(fwrite(&version, sizeof version, 1, fp) == 1);
    assert(fwrite(&file_type, sizeof file_type, 1, fp) == 1);
    fclose(fp);
  }
  gkyl_comm_barrier(app->comm);
  for (int s = 0; s < 2; ++s) {
    struct gk_species *gks = &app->species[s];
    struct gkyl_array *saved = mkarr(false, gks->f->ncomp, gks->f->size);
    gkyl_array_copy(saved, gks->f);
    char fname[128];
    snprintf(fname, sizeof fname, "gk_fluid_species-%s_0.gkyl", gks->info.name);
    gkyl_array_clear(gks->f, 0);
    assert(gk_species_read(app, gks, fname) == GKYL_ARRAY_RIO_SUCCESS);
    gkyl_array_copy(gks->f_host, gks->f);
    check_arrays(gks->f_host, saved, &gks->local);
    struct gkyl_app_restart_status restart = gkyl_gyrokinetic_app_from_file_species(app, s, fname);
    assert(restart.io_status == GKYL_ARRAY_RIO_SUCCESS && restart.frame == 0 && restart.stime == 0);

    const char *bad_files[] = {
      "gk_fluid_species-no-such-file.gkyl", "gk_fluid_species-truncated.gkyl"
    };
    for (int i = 0; i < 2; ++i) {
      assert(gk_species_read(app, gks, bad_files[i]) != GKYL_ARRAY_RIO_SUCCESS);
      restart = gkyl_gyrokinetic_app_from_file_species(app, s, bad_files[i]);
      assert(restart.io_status != GKYL_ARRAY_RIO_SUCCESS);
      gkyl_array_copy(gks->f_host, gks->f);
      check_arrays(gks->f_host, saved, &gks->local);
    }

    // All fixtures have valid payloads. Only their metadata, grid, or component count differs.
    for (int variant = 0; variant < 12; ++variant) {
      struct gkyl_msgpack_map_elem meta[] = {
        {.key = "poly_order", .elem_type = GKYL_MP_UNSIGNED_INT, .uval = gks->basis.poly_order},
        {.key = "basis_type", .elem_type = GKYL_MP_STRING, .cval = gks->basis.id},
        {.key = "vdim", .elem_type = GKYL_MP_UNSIGNED_INT, .uval = gks->info.vdim},
        {
          .key = "state_layout",
          .elem_type = GKYL_MP_STRING,
          .cval = gks->is_fluid ? "Jrho,JMpar,JE,Jpperp/B" : "f",
        },
        {
          .key = "species_representation",
          .elem_type = GKYL_MP_STRING,
          .cval = gks->is_fluid ? "fluid" : "kinetic",
        }
      };
      struct gkyl_rect_grid grid = gks->grid;
      int num_meta = 5;
      if (variant == 1) {
        num_meta = 3; // Legacy kinetic metadata.
      }
      if (variant == 2) {
        num_meta = 0; // Metadata-free kinetic state.
      }
      if (variant == 3) {
        meta[0].uval += 1;
      }
      if (variant == 4) {
        meta[1].cval = "wrong-basis";
      }
      if (variant == 5) {
        meta[2].uval += 1;
      }
      if (variant == 6) {
        meta[3].cval = gks->is_fluid ? "Jn,upar,Tpar/m,Tperp/m" : "Jrho,JMpar,JE,Jpperp/B";
      }
      if (variant == 7) {
        meta[4].cval = gks->is_fluid ? "kinetic" : "fluid";
      }
      if (variant == 8) {
        grid.upper[0] += 1;
      }
      if (variant == 9) {
        grid.cells[0] += 1;
      }
      // Extra components and a wrong element type must be rejected before copying payloads.
      struct gkyl_array *payload =
        variant == 10 ? mkarr(false, saved->ncomp + 1, saved->size) :
        variant == 11 ? gkyl_array_new(GKYL_FLOAT, saved->ncomp, saved->size) :
                        gkyl_array_acquire(saved);
      struct gkyl_msgpack_data *metadata = num_meta ? gkyl_msgpack_create(num_meta, meta) : 0;
      assert(
        gkyl_comm_array_write(
          gks->comm, &grid, &gks->local, metadata, payload, "gk_fluid_species-read-fixture.gkyl"
        ) == 0
      );
      gkyl_msgpack_data_release(metadata);
      gkyl_array_release(payload);
      bool valid = variant == 0 || (!gks->is_fluid && variant <= 2);
      enum gkyl_array_rio_status status =
        gk_species_read(app, gks, "gk_fluid_species-read-fixture.gkyl");
      assert(status == (valid ? GKYL_ARRAY_RIO_SUCCESS : GKYL_ARRAY_RIO_DATA_MISMATCH));
      gkyl_array_copy(gks->f_host, gks->f);
      check_arrays(gks->f_host, saved, &gks->local);
    }
    gkyl_array_release(saved);
  }
}

static void
check_state(gkyl_gyrokinetic_app *app, double density)
{
  struct gk_species *elc = &app->species[1];
  gkyl_array_copy(elc->f_host, elc->f);
  int nb = app->basis.num_basis;
  struct gkyl_range_iter iter;
  gkyl_range_iter_init(&iter, &app->local);
  while (gkyl_range_iter_next(&iter)) {
    const double *f = gkyl_array_cfetch(elc->f_host, gkyl_range_idx(&app->local, iter.idx));
    // J=2, n=density, u=0.3, Tpar/m=5, Tperp/m=7.
    double rho = 0.1 * density;
    double expected[] = {2 * rho, 2 * rho * 0.3, rho * (5 + 0.09) + 2 * rho * 7, 2 * rho * 7};
    for (int c = 0; c < 4; ++c) {
      assert(gkyl_compare(f[c * nb], sqrt(2.0) * expected[c], 1e-10));
      for (int k = 1; k < nb; ++k) {
        assert(fabs(f[c * nb + k]) < 1e-10);
      }
    }
  }
}

static void
check_other_scaling(gkyl_gyrokinetic_app *app)
{
  struct gk_species *fluid = &app->species[1], *ion = &app->species[0];
  struct gkyl_gyrokinetic_scaling_inp saved = fluid->info.scaling;
  struct gk_scaling scaling = {0};
  fluid->info.scaling = (struct gkyl_gyrokinetic_scaling_inp){
    .type = GKYL_GK_SPECIES_SCALING_FIXED_FRACTION,
    .ref_species_name = "ion",
    .fixed_fraction = 0.7,
  };
  gk_species_scaling_init(app, fluid, &scaling);
  gk_species_scaling_cross_init(app, fluid, &scaling);
  gk_species_moment_calc(&ion->m0, ion->local, app->local, ion->f);
  gkyl_array_copy(ion->m0.marr_host, ion->m0.marr);
  const double *ref =
    gkyl_array_cfetch(ion->m0.marr_host, gkyl_range_idx(&app->local, app->local.lower));
  double target = 0.7 * ref[0] / (2 * sqrt(2.0)); // Remove J=2 and basis normalization.
  for (int repeat = 0; repeat < 2; ++repeat) {
    gk_species_scaling_apply(app, fluid, &scaling, fluid->f, 0);
    check_state(app, target);
  }
  gk_species_scaling_release(app, &scaling);

  // Exercise the Boltzmann scaling module with prescribed sheath data.
  // The adiabatic field solver used in this test does not itself allocate sheath values.
  struct gkyl_array *saved_sheath = app->field->sheath_vals[0];
  app->field->sheath_vals[0] = mkarr(app->use_gpu, 2 * app->basis.num_basis, app->local_ext.volume);
  gkyl_array_clear(app->field->sheath_vals[0], 0);
  gkyl_array_shiftc(app->field->sheath_vals[0], sqrt(2.0) * 1.3, 0);
  gkyl_array_shiftc(app->field->sheath_vals[0], sqrt(2.0) * 0.1, app->basis.num_basis);
  fluid->info.scaling =
    (struct gkyl_gyrokinetic_scaling_inp){.type = GKYL_GK_SPECIES_SCALING_BOLTZMANN};
  scaling = (struct gk_scaling){0};
  gk_species_scaling_init(app, fluid, &scaling);
  target = 1.3 * exp((0.25 - 0.1) / (19.0 / 30));
  for (int repeat = 0; repeat < 2; ++repeat) {
    gk_species_scaling_apply(app, fluid, &scaling, fluid->f, 0);
    check_state(app, target);
  }
  gk_species_scaling_release(app, &scaling);
  gkyl_array_release(app->field->sheath_vals[0]);
  app->field->sheath_vals[0] = saved_sheath;
  fluid->info.scaling = saved;
  // Restoring the adiabatic response must use its original t=0 coefficients.
  gk_species_scaling_apply(app, fluid, &fluid->sca, fluid->f, 0);
  check_state(app, 2 * (1 + 0.25 / (19.0 / 30)));
}

static void
check_kinetic_imports(struct gkyl_gk inp, gkyl_gyrokinetic_app *donor)
{
  struct gk_species *ion = &donor->species[0];
  gk_species_moment_calc(&ion->m0, ion->local, donor->local, ion->f);
  gkyl_array_copy(ion->m0.marr_host, ion->m0.marr);
  const double *dens =
    gkyl_array_cfetch(ion->m0.marr_host, gkyl_range_idx(&donor->local, donor->local.lower));
  double density = dens[0] / sqrt(2.0); // Weighted density is constant in configuration space.
  struct gkyl_array *jac = mkarr(false, donor->basis.num_basis, donor->local_ext.volume);
  gkyl_array_copy(jac, donor->gk_geom->geo_int.jacobtot_inv);
  gkyl_comm_array_write(
    donor->comm, &donor->grid, &donor->local, 0, jac, "gk_fluid_species-jacobtot-inv.gkyl"
  );
  gkyl_array_release(jac);
  jac = mkarr(false, ion->vel_map->jacobvel->ncomp, ion->vel_map->jacobvel->size);
  gkyl_array_copy(jac, ion->vel_map->jacobvel);
  gkyl_comm_array_write(
    ion->comm, &ion->grid, &ion->local, 0, jac, "gk_fluid_species-jacobvel.gkyl"
  );
  gkyl_array_release(jac);
  double factor = 1.4;
  for (int variant = 0; variant < 6; ++variant) {
    struct gkyl_gk target = inp;
    target.species[0].init_from_file = (struct gkyl_gyrokinetic_ic_import){
      .type = GKYL_IC_IMPORT_F,
      .file_name = "gk_fluid_species-ion_0.gkyl",
    };
    if (variant == 1) {
      target.species[0].init_from_file.type = GKYL_IC_IMPORT_AF;
      target.species[0].init_from_file.conf_scale = constant;
      target.species[0].init_from_file.conf_scale_ctx = &factor;
    }
    if (variant == 2) {
      target.species[0].init_from_file.enforce_positivity = true;
    }
    if (variant == 3) {
      snprintf(
        target.species[0].init_from_file.jacobtot_inv_file_name, 128,
        "gk_fluid_species-jacobtot-inv.gkyl"
      );
      snprintf(
        target.species[0].init_from_file.jacobvel_file_name, 128, "gk_fluid_species-jacobvel.gkyl"
      );
    }
    if (variant == 4) {
      target.cells[0] *= 2; // Exercise configuration-space interpolation.
    }
    if (variant == 5) {
      // Expand 1x2v into 2x2v, retaining the parallel grid and its decomposition.
      target.cdim = 2;
      target.lower[1] = target.lower[0];
      target.upper[1] = target.upper[0];
      target.cells[1] = target.cells[0];
      target.cells[0] = 2;
      target.parallelism.cuts[1] = target.parallelism.cuts[0];
      target.parallelism.cuts[0] = 1;
      target.num_periodic_dir = 2;
      target.periodic_dirs[1] = 1;
    }
    gkyl_gyrokinetic_app *app = gkyl_gyrokinetic_app_new(&target);
    struct gk_species *species = &app->species[0];
    double expected = density * (variant == 1 ? factor : 1);
    // Constructor import is complete before apply_ic, which must not reload it.
    for (int repeat = 0; repeat < 2; ++repeat) {
      gk_species_moment_calc(&species->m0, species->local, app->local, species->f);
      gkyl_array_copy(species->m0.marr_host, species->m0.marr);
      struct gkyl_range_iter iter;
      gkyl_range_iter_init(&iter, &app->local);
      while (gkyl_range_iter_next(&iter)) {
        const double *m0 =
          gkyl_array_cfetch(species->m0.marr_host, gkyl_range_idx(&app->local, iter.idx));
        assert(gkyl_compare(m0[0], pow(sqrt(2.0), app->cdim) * expected, 1e-10));
        for (int k = 1; k < app->basis.num_basis; ++k) {
          assert(fabs(m0[k]) < 1e-10);
        }
      }
      gkyl_array_scale(species->f, factor);
      expected *= factor;
      gkyl_gyrokinetic_app_apply_ic_species(app, 0, 0);
    }
    gkyl_gyrokinetic_app_apply_ic(app, 0);
    gkyl_gyrokinetic_app_release(app);
  }
}

static void
run_test(struct gkyl_app_args args, enum gkyl_collision_id collision_id, bool norm_nu, bool implicit)
{
  bool use_gpu = args.use_gpu;
  double dens = 2, upar = 0.3, temp = 1, tpar = 0.5, tperp = 0.7, bmag = 1, nu = 0.01;
  struct gkyl_gyrokinetic_species ion = {
    .name = "ion",
    .charge = 1,
    .mass = 1,
    .vdim = 2,
    .lower = {-6, 0},
    .upper = {6, 12},
    .cells = {12, 8},
    .polarization_density = 2,
    .projection =
      {
        .proj_id = GKYL_PROJ_MAXWELLIAN_PRIM,
        .density = constant,
        .ctx_density = &dens,
        .upar = constant,
        .ctx_upar = &upar,
        .temp = constant,
        .ctx_temp = &temp,
      },
    .collisionless = {.type = GKYL_GK_COLLISIONLESS_ES},
    .collisions =
      {
        .collision_id = collision_id,
        .self_nu = constant,
        .self_nu_ctx = &nu,
        .num_cross_collisions = 1,
        .collide_with = {"elc"},
        .cross_nu = {constant},
        .cross_nu_ctx = &nu,
        .den_ref = 2,
        .temp_ref = 1,
      },
  };
  struct gkyl_gyrokinetic_species elc = {
    .name = "elc",
    .charge = -1,
    .mass = 0.1,
    .projection =
      {
        .proj_id = GKYL_PROJ_BIMAXWELLIAN,
        .density = constant,
        .ctx_density = &dens,
        .upar = constant,
        .ctx_upar = &upar,
        .temppar = constant,
        .ctx_temppar = &tpar,
        .tempperp = constant,
        .ctx_tempperp = &tperp,
      },
    .scaling = {.type = GKYL_GK_SPECIES_SCALING_ADIABATIC},
    .collisions =
      {
        .collision_id = collision_id,
        .not_in_dfdt = true,
        .self_nu = constant,
        .self_nu_ctx = &nu,
        .num_cross_collisions = 1,
        .collide_with = {"ion"},
        .cross_nu = {constant},
        .cross_nu_ctx = &nu,
        .den_ref = 2,
        .temp_ref = 19.0 / 30,
      },
    .num_diag_moments = 3,
    .diag_moments = {GKYL_F_MOMENT_M0, GKYL_F_MOMENT_BIMAXWELLIAN, GKYL_F_MOMENT_HAMILTONIAN},
    .num_integrated_diag_moments = 1,
    .integrated_diag_moments = {GKYL_F_MOMENT_HAMILTONIAN},
  };
  struct gkyl_comm *comm = gkyl_gyrokinetic_comms_new(args.use_mpi, use_gpu, stderr);
  ion.collisions.is_implicit = elc.collisions.is_implicit = implicit;
  if (norm_nu) {
    ion.collisions.self_nu = elc.collisions.self_nu = 0;
    ion.collisions.cross_nu[0] = elc.collisions.cross_nu[0] = 0;
    ion.collisions.eps0 = elc.collisions.eps0 = 1;
    ion.collisions.hbar = elc.collisions.hbar = 0.01;
    ion.collisions.eV = elc.collisions.eV = 1;
  }
  struct gkyl_gk inp = {
    .name = "gk_fluid_species",
    .cdim = 1,
    .lower = {-1},
    .upper = {1},
    .cells = {4},
    .poly_order = 1,
    .basis_type = GKYL_BASIS_MODAL_SERENDIPITY,
    .geometry =
      {
        .geometry_id = GKYL_GEOMETRY_MAPC2P,
        .mapc2p = mapc2p,
        .bfield_func = magnetic_field,
        .bfield_ctx = &bmag,
      },
    .num_periodic_dir = 1,
    .periodic_dirs = {0},
    .num_species = 2,
    .species = {ion, elc},
    .parallelism = {.use_gpu = use_gpu, .cuts = {args.cuts[0]}, .comm = comm},
  };
  gkyl_gyrokinetic_app *app = gkyl_gyrokinetic_app_new(&inp);
  struct gk_species *fluid = &app->species[1];
  assert(fluid->is_fluid && fluid->info.vdim == 2);
  assert(fluid->grid.ndim == app->cdim && fluid->basis.num_basis == app->basis.num_basis);
  assert(fluid->f->size == app->local_ext.volume && fluid->f->ncomp == 4 * app->basis.num_basis);
  assert(!fluid->vel_map && !fluid->lte.f_lte && !fluid->lte.proj_max);
  assert(!fluid->lbo.coll_slvr && !fluid->bgk.up_bgk);
  gkyl_gyrokinetic_app_apply_ic(app, 0);
  // Set a known potential and verify the adiabatic closure uses the scalar temperature.
  gkyl_array_clear(app->field->phi_smooth, 0);
  gkyl_array_shiftc(app->field->phi_smooth, sqrt(2.0) * 0.25, 0);
  gk_species_scaling_apply(app, fluid, &fluid->sca, fluid->f, 0);
  double response = dens * (1 + 0.25 / (19.0 / 30));
  check_state(app, response);
  // Reapplying the closure must not compound the response.
  gk_species_scaling_apply(app, fluid, &fluid->sca, fluid->f, 0);
  check_state(app, response);
  check_other_scaling(app);
  // Primitive-moment imports must project the same fluid state without an LTE distribution.
  gk_species_write_mom(app, fluid, 0, 0);
  struct gkyl_gyrokinetic_projection import = {.proj_id = GKYL_PROJ_BIMAXWELLIAN};
  import.bimaxwellian_moms_import.type = GKYL_IC_IMPORT_F;
  snprintf(
    import.bimaxwellian_moms_import.file_name, sizeof import.bimaxwellian_moms_import.file_name,
    "%s-elc_%s_0.gkyl", inp.name, gkyl_distribution_moments_strs[GKYL_F_MOMENT_BIMAXWELLIAN]
  );
  struct gk_proj projection;
  gk_species_projection_init(app, fluid, import, &projection);
  gk_species_projection_calc(app, fluid, &projection, fluid->f, 0);
  check_state(app, response);
  gk_species_projection_release(app, &projection);
  gkyl_gyrokinetic_app_write(app, 0, 0);
  check_species_reads(app);
  if (collision_id == GKYL_LBO_COLLISIONS && !norm_nu) {
    check_kinetic_imports(&inp, app);
  }
  assert(gk_species_read(app, fluid, "gk_fluid_species-ion_0.gkyl") == GKYL_ARRAY_RIO_DATA_MISMATCH);
  // Same grid and component count, but the old primitive-state layout must be rejected.
  struct gkyl_msgpack_map_elem old_layout[] = {
    {.key = "state_layout", .elem_type = GKYL_MP_STRING, .cval = "Jn,upar,Tpar/m,Tperp/m"},
    {.key = "vdim", .elem_type = GKYL_MP_UNSIGNED_INT, .uval = 2},
    {.key = "poly_order", .elem_type = GKYL_MP_UNSIGNED_INT, .uval = 1}
  };
  struct gkyl_msgpack_data *metadata = gkyl_msgpack_create(3, old_layout);
  gkyl_comm_array_write(
    fluid->comm, &fluid->grid, &fluid->local, metadata, fluid->f_host,
    "gk_fluid_species-old-layout.gkyl"
  );
  gkyl_msgpack_data_release(metadata);
  assert(
    gk_species_read(app, fluid, "gk_fluid_species-old-layout.gkyl") == GKYL_ARRAY_RIO_DATA_MISMATCH
  );
  check_state(app, response);
  gkyl_gyrokinetic_app_calc_integrated_mom(app, 0);
  gkyl_gyrokinetic_app_write_integrated_mom(app);
  // Restart into a fresh app, as the simulation driver does.
  gkyl_gyrokinetic_app_release(app);
  // A full-state import retains the conservative representation exactly.
  inp.species[1].init_from_file.type = GKYL_IC_IMPORT_F;
  snprintf(
    inp.species[1].init_from_file.file_name, sizeof inp.species[1].init_from_file.file_name,
    "gk_fluid_species-elc_0.gkyl"
  );
  app = gkyl_gyrokinetic_app_new(&inp);
  // The file has already been imported by the constructor.
  check_state(app, response);
  gkyl_array_scale(app->species[1].f, 1.25);
  gkyl_gyrokinetic_app_apply_ic_species(app, 1, 0);
  check_state(app, 1.25 * response); // apply_ic must not reread the file.
  gkyl_gyrokinetic_app_apply_ic(app, 0); // Initialize the field before releasing the app.
  gkyl_gyrokinetic_app_release(app);
  inp.species[1].init_from_file.type = GKYL_IC_IMPORT_NONE;
  app = gkyl_gyrokinetic_app_new(&inp);
  fluid = &app->species[1];
  struct gkyl_app_restart_status restart = gkyl_gyrokinetic_app_read_from_frame(app, 0);
  assert(restart.io_status == GKYL_ARRAY_RIO_SUCCESS);
  check_state(app, response);
  struct gkyl_update_status status = gkyl_gyrokinetic_update(app, 1e-4);
  assert(status.success && isfinite(status.dt_actual));
  if (collision_id == GKYL_LBO_COLLISIONS) {
    struct gkyl_array *host =
      gkyl_array_new(GKYL_DOUBLE, fluid->lbo.prim_moms->ncomp, fluid->lbo.prim_moms->size);
    gkyl_array_copy(host, fluid->lbo.prim_moms);
    const double *prim = gkyl_array_cfetch(host, gkyl_range_idx(&app->local, app->local.lower));
    assert(gkyl_compare(prim[0], sqrt(2.0) * upar, 1e-10));
    assert(gkyl_compare(prim[app->basis.num_basis], sqrt(2.0) * 19.0 / 3, 1e-10));
    gkyl_array_release(host);
  }
  gkyl_gyrokinetic_app_release(app);
  gkyl_gyrokinetic_comms_release(comm);
}

int
main(int argc, char **argv)
{
  struct gkyl_app_args args = parse_app_args(argc, argv);
#ifdef GKYL_HAVE_MPI
  if (args.use_mpi) {
    MPI_Init(&argc, &argv);
  }
#endif
  run_test(args, GKYL_LBO_COLLISIONS, false, false);
  run_test(args, GKYL_LBO_COLLISIONS, true, false);
  run_test(args, GKYL_BGK_COLLISIONS, false, false);
  run_test(args, GKYL_BGK_COLLISIONS, true, false);
  run_test(args, GKYL_BGK_COLLISIONS, true, true);
#ifdef GKYL_HAVE_MPI
  if (args.use_mpi) {
    MPI_Finalize();
  }
#endif
  puts("Fluid species projection, scaling, collision partners, and restart: passed.");
  return 0;
}

