  status = gkyl_comm_array_read(gks->comm, &gks->grid, &gks->local, gks->f_host, fname);
  if (status == GKYL_ARRAY_RIO_SUCCESS && app->use_gpu) {
    gkyl_array_copy(gks->f, gks->f_host);
  }
  return status;
}

