        {
          .key = "species_model",
          .elem_type = GKYL_MP_STRING,
          .cval = gks->is_fluid ? "gyrofluid" : "gyrokinetic",
        }
      };
      struct gkyl_rect_grid grid = gks->grid;
      int num_meta = 5;
      if (variant == 1) {
        num_meta = 3; // Metadata without layout or species model.
      }
      if (variant == 2) {
        num_meta = 0; // Metadata-free state, valid for either species model.
      }
      if (variant == 3) {
        meta[0].uval += 1;
      }
      if (variant == 4) {
        meta[1].cval = "wrong-basis";
      }
      if (variant == 5) {
        meta[2].uval += 1;
      }
      if (variant == 6) {
        meta[3].cval = "invalid-layout";
      }
      if (variant == 7) {
        meta[4].cval = gks->is_fluid ? "gyrokinetic" : "gyrofluid";
      }
      if (variant == 8) {
        grid.upper[0] += 1;
      }
      if (variant == 9) {
        grid.cells[0] += 1;
      }
      if (variant >= 12) {
        // Each metadata key is independently optional.
        meta[variant - 12].key = "unused_metadata";
      }
      // Extra components and a wrong element type must be rejected before copying payloads.
      struct gkyl_array *payload =
        variant == 10 ? mkarr(false, saved->ncomp + 1, saved->size) :
        variant == 11 ? gkyl_array_new(GKYL_FLOAT, saved->ncomp, saved->size) :
                        gkyl_array_acquire(saved);
      struct gkyl_msgpack_data *metadata = num_meta ? gkyl_msgpack_create(num_meta, meta) : 0;
      assert(
        gkyl_comm_array_write(
          gks->comm, &grid, &gks->local, metadata, payload, "gk_fluid_species-read-fixture.gkyl"
        ) == 0
      );
      gkyl_msgpack_data_release(metadata);
      gkyl_array_release(payload);
      bool valid = variant <= 2 || variant >= 12;
      enum gkyl_array_rio_status status =
        gk_species_read(app, gks, "gk_fluid_species-read-fixture.gkyl");
      assert(status == (valid ? GKYL_ARRAY_RIO_SUCCESS : GKYL_ARRAY_RIO_DATA_MISMATCH));
      gkyl_array_copy(gks->f_host, gks->f);
      check_arrays(gks->f_host, saved, &gks->local);
    }
    gkyl_array_release(saved);
  }
}

