// Copy one DG component through scalar scratch, including between vector arrays.
static void
gk_fluid_moments_copy(
  const struct gkyl_gk_fluid_moments *up, const struct gkyl_range *range, struct gkyl_array *out,
  int oc, double rmass_fac, const struct gkyl_array *inp, int ic
)
{
  int nb = up->basis.num_basis;
  gkyl_array_set_offset_range(up->tmp, rmass_fac, inp, ic * nb, range);
  gkyl_array_set_offset_range(out, 1.0, up->tmp, oc * nb, range);
}

static void
gk_fluid_moments_perp(
  const struct gkyl_gk_fluid_moments *up, const struct gkyl_range *range,
  const struct gkyl_array *state
)
{
  gkyl_dg_mul_op_range(&up->basis, 0, up->pperp, 0, up->bmag, 3, state, range);
}

static void
gk_fluid_moments_perp_zero(
  const struct gkyl_gk_fluid_moments *up, const struct gkyl_range *range,
  const struct gkyl_array *state
)
{
  gkyl_array_clear_range(up->pperp, 0.0, range);
}

static void
gk_fluid_moments_project_perp(
  const struct gkyl_gk_fluid_moments *up, const struct gkyl_range *range,
  const struct gkyl_array *state, const struct gkyl_array *prim
)
{
  gkyl_dg_mul_op_range(&up->basis, 0, up->pperp, 0, state, 3, prim, range);
}

static void
gk_fluid_moments_project_perp_zero(
  const struct gkyl_gk_fluid_moments *up, const struct gkyl_range *range,
  const struct gkyl_array *state, const struct gkyl_array *prim
)
{
  gkyl_array_clear_range(up->pperp, 0.0, range);
}

// Recover u and weighted pressures. No division by J is needed.
static void
gk_fluid_moments_recover(
  const struct gkyl_gk_fluid_moments *up, const struct gkyl_range *range,
  const struct gkyl_array *state
)
{
  gkyl_dg_div_op_range(up->mem, &up->basis, 0, up->upar, 1, state, 0, state, range);
  up->perp(up, range, state);
  gkyl_dg_mul_op_range(&up->basis, 0, up->ppar, 0, up->upar, 1, state, range);
  gkyl_array_scale_range(up->ppar, -1.0, range);
  gkyl_array_set_offset_range(up->tmp, 2.0, state, 2 * up->basis.num_basis, range);
  gkyl_array_accumulate_range(up->ppar, 1.0, up->tmp, range);
  gkyl_array_accumulate_range(up->ppar, -2.0, up->pperp, range);
}

static void
gk_fluid_moments_linear(
  const struct gkyl_gk_fluid_moments *up, const struct gkyl_range *range,
  const struct gkyl_array *state, const struct gkyl_array *phi
)
{
  gk_fluid_moments_copy(up, range, up->result, 0, up->rmass_fac, state, up->component);
}

static void
gk_fluid_moments_m2perp(
  const struct gkyl_gk_fluid_moments *up, const struct gkyl_range *range,
  const struct gkyl_array *state, const struct gkyl_array *phi
)
{
  up->perp(up, range, state);
  gk_fluid_moments_copy(up, range, up->result, 0, 2.0 / up->mass, up->pperp, 0);
}

static void
gk_fluid_moments_m2par(
  const struct gkyl_gk_fluid_moments *up, const struct gkyl_range *range,
  const struct gkyl_array *state, const struct gkyl_array *phi
)
{
  up->perp(up, range, state);
  gkyl_array_set_offset_range(up->ppar, 2.0 / up->mass, state, 2 * up->basis.num_basis, range);
  gkyl_array_accumulate_range(up->ppar, -2.0 / up->mass, up->pperp, range);
  gk_fluid_moments_copy(up, range, up->result, 0, 1.0, up->ppar, 0);
}

static void
gk_fluid_moments_m3par(
  const struct gkyl_gk_fluid_moments *up, const struct gkyl_range *range,
  const struct gkyl_array *state, const struct gkyl_array *phi
)
{
  gk_fluid_moments_recover(up, range, state);
  // M3par = u*(M2par+2*J*ppar/m).
  gkyl_array_scale_range(up->ppar, 2.0 / up->mass, range);
  gkyl_array_set_offset_range(up->tmp, 2.0 / up->mass, state, 2 * up->basis.num_basis, range);
  gkyl_array_accumulate_range(up->ppar, 1.0, up->tmp, range);
  gkyl_array_accumulate_range(up->ppar, -2.0 / up->mass, up->pperp, range);
