struct gkyl_gk_fluid_moments *
gkyl_gk_fluid_moments_inew(const struct gkyl_gk_fluid_moments_inp *inp)
{
  assert(inp->vdim == 1 || inp->vdim == 2);
  assert(inp->mass > 0 && inp->bmag);

  struct gkyl_gk_fluid_moments *up = gkyl_malloc(sizeof *up);

  *up = (struct gkyl_gk_fluid_moments){
    .basis = *inp->basis,
    .vdim = inp->vdim,
    .mass = inp->mass,
    .charge = inp->charge,
    .num_mom = 1,
    .num_cells = inp->range->volume,
    .rmass_fac = 1.0 / inp->mass,
    .volnorm_fac = 1.0,
    .perp = inp->vdim == 1 ? gk_fluid_moments_perp_zero : gk_fluid_moments_perp,
    .project_perp = inp->vdim == 1 ? gk_fluid_moments_project_perp_zero :
                                     gk_fluid_moments_project_perp,
    .finish = inp->integrated ? gk_fluid_moments_integrate : gk_fluid_moments_finish,
  };

  switch (inp->moment) {
    case GKYL_F_MOMENT_M0:
    case GKYL_F_MOMENT_M1:
    case GKYL_F_MOMENT_M2:
      up->component = inp->moment == GKYL_F_MOMENT_M0 ? 0 : inp->moment == GKYL_F_MOMENT_M1 ? 1 : 2;
      up->rmass_fac *= up->component == 2 ? 2.0 : 1.0;
      up->calc = gk_fluid_moments_linear;
      break;
    case GKYL_F_MOMENT_M2PAR:
      up->calc = gk_fluid_moments_m2par;
      break;
    case GKYL_F_MOMENT_M2PERP:
      up->calc = gk_fluid_moments_m2perp;
      break;
    case GKYL_F_MOMENT_M3PAR:
      up->calc = gk_fluid_moments_m3par;
      break;
    case GKYL_F_MOMENT_M3PERP:
      up->calc = gk_fluid_moments_m3perp;
      break;
    case GKYL_F_MOMENT_MAXWELLIAN:
      up->num_mom = 3;
      up->calc = gk_fluid_moments_maxwellian;
      break;
    case GKYL_F_MOMENT_BIMAXWELLIAN:
      up->num_mom = 4;
      up->calc = gk_fluid_moments_bimaxwellian;
      break;
    case GKYL_F_MOMENT_M0M1M2:
      up->num_mom = 3;
      up->calc = gk_fluid_moments_m0m1m2;
      break;
    case GKYL_F_MOMENT_M0M1M2PARM2PERP:
      up->num_mom = inp->vdim + 2;
      up->calc = gk_fluid_moments_m0m1m2parperp;
      break;
    case GKYL_F_MOMENT_HAMILTONIAN:
      up->num_mom = 3;
      up->calc = gk_fluid_moments_hamiltonian;
      break;
