}

int
gkyl_gk_fluid_moments_num_mom(const struct gkyl_gk_fluid_moments *up)
{
  return up->num_mom;
}

extern "C" {
#include <gkyl_gk_fluid_moments_priv.h>
}

__global__ static void
gk_fluid_moments_integrate_kernel(
  int nb, int nm, double rmass_fac, struct gkyl_range range, const struct gkyl_array *result,
  struct gkyl_array *out
)
{
  int idx[GKYL_MAX_DIM];
