struct gkyl_gk_fluid_moments {
  struct gkyl_basis basis; // Configuration-space basis.
  int num_mom; // Number of output moments.
  int vdim; // Velocity-space dimension (1 or 2).
  int component; // Conservative-state component used for M0, M1, or M2.
  long num_cells; // Batch size of the weak division solves.
  double mass; // Species mass.
  double charge; // Species charge.
  double volnorm_fac; // Converts the constant DG coefficient to a cell integral.
  double rmass_fac; // State-to-moment factor: 1/m for M0 and M1, 2/m for M2.
  struct gkyl_array *bmag; // Acquired magnetic-field magnitude.
  struct gkyl_array *upar; // Parallel-velocity scratch, also reused for conversion and scaling.
  struct gkyl_array *ppar; // Jacobian-weighted parallel-pressure scratch and intermediate results.
  struct gkyl_array *pperp; // Jacobian-weighted perpendicular-pressure scratch (zero in 1v).
  struct gkyl_array *tmp; // Scalar scratch for copying and scaling DG components.
  struct gkyl_array *result; // DG coefficients of calculated moments, before output or integration.
  gkyl_dg_bin_op_mem *mem; // Preallocated workspace for weak-DG division.
  // Methods selected at initialization:
  // Calculate the requested moments into result.
  void (*calc)(const struct gkyl_gk_fluid_moments *, const struct gkyl_range *, const struct gkyl_array *, const struct gkyl_array *);
  // Copy DG moments to output or compute their cell integrals.
  void (*finish)(const struct gkyl_gk_fluid_moments *, const struct gkyl_range *, struct gkyl_array *);
  // Recover J*pperp from the conservative state, or set it to zero in 1v.
  void (*perp)(const struct gkyl_gk_fluid_moments *, const struct gkyl_range *, const struct gkyl_array *);
  // Construct J*pperp from primitive temperature, or set it to zero in 1v.
  void (*project_perp)(const struct gkyl_gk_fluid_moments *, const struct gkyl_range *, const struct gkyl_array *, const struct gkyl_array *);
};

