}

struct gkyl_gk_fluid_moments *
gkyl_gk_fluid_moments_inew(const struct gkyl_gk_fluid_moments_inp *inp)
{
  assert(inp->vdim == 1 || inp->vdim == 2);
  assert(inp->mass > 0 && inp->bmag);

  struct gkyl_gk_fluid_moments *up = gkyl_malloc(sizeof *up);

  *up = (struct gkyl_gk_fluid_moments){
    .basis = *inp->basis,
    .vdim = inp->vdim,
    .mass = inp->mass,
    .charge = inp->charge,
    .num_mom = 1,
    .num_cells = inp->range->volume,
    .rmass_fac = 1.0 / inp->mass,
    .volnorm_fac = 1.0,
    .perp = inp->vdim == 1 ? gk_fluid_moments_perp_zero : gk_fluid_moments_perp,
    .project_perp = inp->vdim == 1 ? gk_fluid_moments_project_perp_zero :
                                     gk_fluid_moments_project_perp,
    .finish = inp->integrated ? gk_fluid_moments_integrate : gk_fluid_moments_finish,
  };

  switch (inp->moment) {
    case GKYL_F_MOMENT_M0:
    case GKYL_F_MOMENT_M1:
    case GKYL_F_MOMENT_M2:
      up->component = inp->moment == GKYL_F_MOMENT_M0 ? 0 : inp->moment == GKYL_F_MOMENT_M1 ? 1 : 2;
      up->rmass_fac *= up->component == 2 ? 2.0 : 1.0;
      up->calc = gk_fluid_moments_linear;
      break;
    case GKYL_F_MOMENT_M2PAR:
      up->calc = gk_fluid_moments_m2par;
      break;
    case GKYL_F_MOMENT_M2PERP:
      up->calc = gk_fluid_moments_m2perp;
      break;
    case GKYL_F_MOMENT_M3PAR:
      up->calc = gk_fluid_moments_m3par;
      break;
    case GKYL_F_MOMENT_M3PERP:
      up->calc = gk_fluid_moments_m3perp;
      break;
    case GKYL_F_MOMENT_MAXWELLIAN:
      up->num_mom = 3;
      up->calc = gk_fluid_moments_maxwellian;
      break;
    case GKYL_F_MOMENT_BIMAXWELLIAN:
      up->num_mom = 4;
      up->calc = gk_fluid_moments_bimaxwellian;
      break;
    case GKYL_F_MOMENT_M0M1M2:
      up->num_mom = 3;
      up->calc = gk_fluid_moments_m0m1m2;
      break;
    case GKYL_F_MOMENT_M0M1M2PARM2PERP:
      up->num_mom = inp->vdim + 2;
      up->calc = gk_fluid_moments_m0m1m2parperp;
      break;
    case GKYL_F_MOMENT_HAMILTONIAN:
      up->num_mom = 3;
      up->calc = gk_fluid_moments_hamiltonian;
      break;
    default:
      gkyl_exit("Unsupported gyrokinetic fluid moment.");
  }

  for (int d = 0; d < inp->grid->ndim; ++d) {
    up->volnorm_fac *= inp->grid->dx[d] / sqrt(2.0);
  }

  struct gkyl_array *(*alloc)(enum gkyl_elem_type, size_t, size_t) =
    inp->use_gpu ? gkyl_array_cu_dev_new : gkyl_array_new;

  int nb = inp->basis->num_basis;

  up->bmag = gkyl_array_acquire(inp->bmag);
  up->upar = alloc(GKYL_DOUBLE, nb, inp->range_ext->volume);
  up->ppar = alloc(GKYL_DOUBLE, nb, inp->range_ext->volume);
  up->pperp = alloc(GKYL_DOUBLE, nb, inp->range_ext->volume);
  up->tmp = alloc(GKYL_DOUBLE, nb, inp->range_ext->volume);
  up->result = alloc(GKYL_DOUBLE, 4 * nb, inp->range_ext->volume);
  up->mem = inp->use_gpu ? gkyl_dg_bin_op_mem_cu_dev_new(inp->range->volume, nb) :
                           gkyl_dg_bin_op_mem_new(inp->range->volume, nb);

#ifdef GKYL_HAVE_CUDA
  if (inp->use_gpu && inp->integrated) {
    up->finish = gkyl_gk_fluid_moments_integrate_cu;
  }
#endif

  return up;
}

int
gkyl_gk_fluid_moments_num_mom(const struct gkyl_gk_fluid_moments *up)
{
  return up->num_mom;
}

extern "C" {
#include <gkyl_gk_fluid_moments_priv.h>
}

__global__ static void
gk_fluid_moments_integrate_kernel(
  int nb, int nm, double rmass_fac, struct gkyl_range range, const struct gkyl_array *result,
  struct gkyl_array *out
)
{
  int idx[GKYL_MAX_DIM];
  for (long cell = threadIdx.x + blockIdx.x * blockDim.x; cell < range.volume;
       cell += gridDim.x * blockDim.x) {
    gkyl_sub_range_inv_idx(&range, cell, idx);
    long loc = gkyl_range_idx(&range, idx);
    const double *dg = (const double *)gkyl_array_cfetch(result, loc);
    double *integral = (double *)gkyl_array_fetch(out, loc);
    for (int c = 0; c < nm; ++c) {
      integral[c] = rmass_fac * dg[c * nb];
    }
  }
}

void
gkyl_gk_fluid_moments_integrate_cu(
  const struct gkyl_gk_fluid_moments *up, const struct gkyl_range *range, struct gkyl_array *out
)
{
  gk_fluid_moments_integrate_kernel<<<range->nblocks, range->nthreads>>>(
    up->basis.num_basis, up->num_mom, up->volnorm_fac, *range, up->result->on_dev, out->on_dev
  );
}
"}

