test_array_scale_ho()
{
  struct gkyl_array *a1 = gkyl_array_new(GKYL_DOUBLE, 1, 10);

  double *a1_d = a1->data;
  for (unsigned i = 0; i < a1->size; ++i) {
    a1_d[i] = i * 1.0;
  }

  gkyl_array_scale(a1, 0.25);

  for (unsigned i = 0; i < a1->size; ++i) {
