static void
run_test(struct gkyl_app_args args, enum gkyl_collision_id collision_id, bool norm_nu, bool implicit)
{
  bool use_gpu = args.use_gpu;
  double dens = 2, upar = 0.3, temp = 1, tpar = 0.5, tperp = 0.7, bmag = 1, nu = 0.01;
  struct gkyl_gyrokinetic_species ion = {
    .name = "ion",
    .charge = 1,
    .mass = 1,
    .vdim = 2,
    .lower = {-6, 0},
    .upper = {6, 12},
    .cells = {12, 8},
    .polarization_density = 2,
    .projection =
      {
        .proj_id = GKYL_PROJ_MAXWELLIAN_PRIM,
        .density = constant,
        .ctx_density = &dens,
        .upar = constant,
        .ctx_upar = &upar,
        .temp = constant,
        .ctx_temp = &temp,
      },
    .collisionless = {.type = GKYL_GK_COLLISIONLESS_ES},
    .collisions =
      {
        .collision_id = collision_id,
        .self_nu = constant,
        .self_nu_ctx = &nu,
        .num_cross_collisions = 1,
        .collide_with = {"elc"},
        .cross_nu = {constant},
        .cross_nu_ctx = &nu,
        .den_ref = 2,
        .temp_ref = 1,
      },
  };
  struct gkyl_gyrokinetic_species elc = {
    .name = "elc",
    .charge = -1,
    .mass = 0.1,
    .projection =
      {
        .proj_id = GKYL_PROJ_BIMAXWELLIAN,
        .density = constant,
        .ctx_density = &dens,
        .upar = constant,
        .ctx_upar = &upar,
        .temppar = constant,
        .ctx_temppar = &tpar,
        .tempperp = constant,
        .ctx_tempperp = &tperp,
      },
    .scaling = {.type = GKYL_GK_SPECIES_SCALING_ADIABATIC},
    .collisions =
      {
        .collision_id = collision_id,
        .not_in_dfdt = true,
        .self_nu = constant,
        .self_nu_ctx = &nu,
        .num_cross_collisions = 1,
        .collide_with = {"ion"},
        .cross_nu = {constant},
        .cross_nu_ctx = &nu,
        .den_ref = 2,
        .temp_ref = 19.0 / 30,
      },
    .num_diag_moments = 3,
    .diag_moments = {GKYL_F_MOMENT_M0, GKYL_F_MOMENT_BIMAXWELLIAN, GKYL_F_MOMENT_HAMILTONIAN},
    .num_integrated_diag_moments = 1,
    .integrated_diag_moments = {GKYL_F_MOMENT_HAMILTONIAN},
  };
  struct gkyl_comm *comm = gkyl_gyrokinetic_comms_new(args.use_mpi, use_gpu, stderr);
  ion.collisions.is_implicit = elc.collisions.is_implicit = implicit;
  if (norm_nu) {
    ion.collisions.self_nu = elc.collisions.self_nu = 0;
    ion.collisions.cross_nu[0] = elc.collisions.cross_nu[0] = 0;
    ion.collisions.eps0 = elc.collisions.eps0 = 1;
    ion.collisions.hbar = elc.collisions.hbar = 0.01;
    ion.collisions.eV = elc.collisions.eV = 1;
  }
  struct gkyl_gk inp = {
    .name = "gk_fluid_species",
    .cdim = 1,
    .lower = {-1},
    .upper = {1},
    .cells = {4},
    .poly_order = 1,
    .basis_type = GKYL_BASIS_MODAL_SERENDIPITY,
    .geometry =
      {
        .geometry_id = GKYL_GEOMETRY_MAPC2P,
        .mapc2p = mapc2p,
        .bfield_func = magnetic_field,
        .bfield_ctx = &bmag,
      },
    .num_periodic_dir = 1,
    .periodic_dirs = {0},
    .num_species = 2,
    .species = {ion, elc},
    .parallelism = {.use_gpu = use_gpu, .cuts = {args.cuts[0]}, .comm = comm},
  };
  gkyl_gyrokinetic_app *app = gkyl_gyrokinetic_app_new(&inp);
  struct gk_species *fluid = &app->species[1];
  assert(fluid->is_fluid && fluid->info.vdim == 2);
  assert(fluid->grid.ndim == app->cdim && fluid->basis.num_basis == app->basis.num_basis);
  assert(fluid->f->size == app->local_ext.volume && fluid->f->ncomp == 4 * app->basis.num_basis);
  assert(!fluid->vel_map && !fluid->lte.f_lte && !fluid->lte.proj_max);
  assert(!fluid->lbo.coll_slvr && !fluid->bgk.up_bgk);
  gkyl_gyrokinetic_app_apply_ic(app, 0);
  // Set a known potential and verify the adiabatic closure uses the scalar temperature.
  gkyl_array_clear(app->field->phi_smooth, 0);
  gkyl_array_shiftc(app->field->phi_smooth, sqrt(2.0) * 0.25, 0);
  gk_species_scaling_apply(app, fluid, &fluid->sca, fluid->f, 0);
  double response = dens * (1 + 0.25 / (19.0 / 30));
  check_state(app, response);
  // Reapplying the closure must not compound the response.
  gk_species_scaling_apply(app, fluid, &fluid->sca, fluid->f, 0);
  check_state(app, response);
  check_other_scaling(app);
  // Primitive-moment imports must project the same fluid state without an LTE distribution.
  gk_species_write_mom(app, fluid, 0, 0);
  struct gkyl_gyrokinetic_projection import = {.proj_id = GKYL_PROJ_BIMAXWELLIAN};
  import.bimaxwellian_moms_import.type = GKYL_IC_IMPORT_F;
  snprintf(
    import.bimaxwellian_moms_import.file_name, sizeof import.bimaxwellian_moms_import.file_name,
    "%s-elc_%s_0.gkyl", inp.name, gkyl_distribution_moments_strs[GKYL_F_MOMENT_BIMAXWELLIAN]
  );
  struct gk_proj projection;
  gk_species_projection_init(app, fluid, import, &projection);
  gk_species_projection_calc(app, fluid, &projection, fluid->f, 0);
  check_state(app, response);
  check_state(app, response);
  gk_species_projection_release(app, &projection);
  gkyl_gyrokinetic_app_write(app, 0, 0);
  check_species_reads(app);
  if (collision_id == GKYL_LBO_COLLISIONS && !norm_nu) {
    check_kinetic_imports(&inp, app);
  }
  assert(gk_species_read(app, fluid, "gk_fluid_species-ion_0.gkyl") == GKYL_ARRAY_RIO_DATA_MISMATCH);
  check_state(app, response);
  gkyl_gyrokinetic_app_calc_integrated_mom(app, 0);
  gkyl_gyrokinetic_app_write_integrated_mom(app);
  // Restart into a fresh app, as the simulation driver does.
  gkyl_gyrokinetic_app_release(app);
  // A full-state import retains the conservative representation exactly.
  inp.species[1].init_from_file.type = GKYL_IC_IMPORT_F;
  snprintf(
    inp.species[1].init_from_file.file_name, sizeof inp.species[1].init_from_file.file_name,
    "gk_fluid_species-elc_0.gkyl"
  );
  app = gkyl_gyrokinetic_app_new(&inp);
  // The file has already been imported by the constructor.
  check_state(app, response);
  gkyl_array_scale(app->species[1].f, 1.25);
  gkyl_gyrokinetic_app_apply_ic_species(app, 1, 0);
  check_state(app, 1.25 * response); // apply_ic must not reread the file.
  gkyl_gyrokinetic_app_apply_ic(app, 0); // Initialize the field before releasing the app.
  gkyl_gyrokinetic_app_release(app);
  inp.species[1].init_from_file.type = GKYL_IC_IMPORT_NONE;
  app = gkyl_gyrokinetic_app_new(&inp);
  fluid = &app->species[1];
  struct gkyl_app_restart_status restart = gkyl_gyrokinetic_app_read_from_frame(app, 0);
  assert(restart.io_status == GKYL_ARRAY_RIO_SUCCESS);
  check_state(app, response);
  struct gkyl_update_status status = gkyl_gyrokinetic_update(app, 1e-4);
  assert(status.success && isfinite(status.dt_actual));
  if (collision_id == GKYL_LBO_COLLISIONS) {
    struct gkyl_array *host =
      gkyl_array_new(GKYL_DOUBLE, fluid->lbo.prim_moms->ncomp, fluid->lbo.prim_moms->size);
    gkyl_array_copy(host, fluid->lbo.prim_moms);
    const double *prim = gkyl_array_cfetch(host, gkyl_range_idx(&app->local, app->local.lower));
    assert(gkyl_compare(prim[0], sqrt(2.0) * upar, 1e-10));
    assert(gkyl_compare(prim[app->basis.num_basis], sqrt(2.0) * 19.0 / 3, 1e-10));
    gkyl_array_release(host);
  }
  gkyl_gyrokinetic_app_release(app);
  gkyl_gyrokinetic_comms_release(comm);
}

int
main(int argc, char **argv)
{
  struct gkyl_app_args args = parse_app_args(argc, argv);
#ifdef GKYL_HAVE_MPI
  if (args.use_mpi) {
    MPI_Init(&argc, &argv);
  }
#endif
  run_test(args, GKYL_LBO_COLLISIONS, false, false);
  run_test(args, GKYL_LBO_COLLISIONS, true, false);
  run_test(args, GKYL_BGK_COLLISIONS, false, false);
  run_test(args, GKYL_BGK_COLLISIONS, true, false);
  run_test(args, GKYL_BGK_COLLISIONS, true, true);
#ifdef GKYL_HAVE_MPI
  if (args.use_mpi) {
    MPI_Finalize();
  }
#endif
  puts("Fluid species projection, scaling, collision partners, and restart: passed.");
  return 0;
}
