      struct gkyl_array *state = gkyl_array_new(GKYL_DOUBLE, 4 * nb, ext.volume);
      struct gkyl_array *phi = gkyl_array_new(GKYL_DOUBLE, nb, ext.volume);
      double norm = pow(sqrt(2.0), cdim);
      // m=2, Jn=2, u=3, Tpar/m=5, Tperp/m=7, B=3.
