        GKYL_F_MOMENT_M0M1M2PARM2PERP,
        GKYL_F_MOMENT_HAMILTONIAN
      };
      double expected[][4] = {
        {2},
        {6},
        {28 + perp},
        {28},
        {perp},
        {144},
        {3 * perp},
        {2, 3, vdim == 2 ? 19.0 / 3 : 5},
        {2, 3, 5, vdim == 2 ? 7 : 0},
        {2, 6, 28 + perp},
        {2, 6, 28, perp},
