      gkyl_array_shiftc(state, perp / 3 * norm, 3 * nb);
      gkyl_array_shiftc(phi, 11 * norm, 0);
      struct gkyl_array *state_dev =
        use_gpu ? gkyl_array_cu_dev_new(GKYL_DOUBLE, state->ncomp, state->size) :
