                                          gkyl_array_new(GKYL_DOUBLE, nb, ext.volume);
      gkyl_array_clear(bmag, 0);
      gkyl_array_shiftc(bmag, 3 * norm, 0);
      enum gkyl_distribution_moments ids[] = {
