      gkyl_array_copy(result, out);
      actual = gkyl_array_cfetch(result, loc);
      for (int c = 0; c < nm; ++c) {
        if (integrated) {
          TEST_CHECK(gkyl_compare(actual[c], 2 * expected[m][c].a, 1e-11));
