// Focused app-level checks of the fluid charged-species representation.
#include <gkyl_gk_species_priv.h>
#include <gkyl_gyrokinetic_comms.h>
#include <rt_arg_parse.h>

static void
constant(double t, const double *xn, double *out, void *ctx)
{
  out[0] = *(double *)ctx;
}

static void
magnetic_field(double t, const double *xn, double *out, void *ctx)
{
  out[0] = out[1] = 0;
  out[2] = *(double *)ctx;
}

static void
mapc2p(double t, const double *xn, double *out, void *ctx)
{
  out[0] = xn[0];
  out[1] = xn[1];
  out[2] = 2 * xn[2];
}

static void
check_arrays(
  const struct gkyl_array *actual, const struct gkyl_array *expected, const struct gkyl_range *range
)
{
  assert(actual->ncomp == expected->ncomp);
  struct gkyl_range_iter iter;
  gkyl_range_iter_init(&iter, range);
  while (gkyl_range_iter_next(&iter)) {
    long loc = gkyl_range_idx(range, iter.idx);
    const double *got = gkyl_array_cfetch(actual, loc), *want = gkyl_array_cfetch(expected, loc);
    for (int c = 0; c < actual->ncomp; ++c) {
      assert(gkyl_compare(got[c], want[c], 1e-11));
    }
  }
}

static void
check_species_reads(gkyl_gyrokinetic_app *app)
{
  int rank;
  gkyl_comm_get_rank(app->comm, &rank);
  if (rank == 0) {
    // Valid magic, version, and file type; truncated before the metadata length.
    FILE *fp = fopen("gk_fluid_species-truncated.gkyl", "wb");
    assert(fp);
    uint64_t version = 1, file_type = 1;
    assert(fwrite("gkyl0", 5, 1, fp) == 1);
    assert(fwrite(&version, sizeof version, 1, fp) == 1);
    assert(fwrite(&file_type, sizeof file_type, 1, fp) == 1);
    fclose(fp);
